func main() {
    args := os.Args[1:]
    // Handle help/version early regardless of other errors?
    for _, a := range args {
        if a == "--help" || a == "-h" {
            fmt.Print(helpText)
            os.Exit(0)
        }
        if a == "--version" || a == "-V" {
            fmt.Print(version)
            os.Exit(0)
        }
    }
    // Parse flags manually to support required logic similar to clap
    // First check for unknown arguments
    knownWithValue := map[string]bool{
        "--bind": true, "-c": true, "--config": true, "--start-theme": true, "--set-theme": true, "--new": true, "-t": true,
        "--name": true, "--tagline": true, "--url": true, "--https": true, "--footer": true, "--language": true, "--pagination": true,
        "--enable-search": true, "--enable-related-content": true, "--content-path": true, "--templates-path": true, "--static-path": true, "--media-path": true,
        "--default-date-format": true, "--colorscheme": true, "--toc": true, "--json-feed": true, "--show-next-prev-links": true, "--publish-md": true,
        "--source-repository": true, "--image-provider": true, "--theme": true, "--build-sitemap": true, "--publish-urls-json": true, "--enable-shortcodes": true, "--shortcode-pattern": true, "--skip-image-resize": true,
    }
    boolFlags := map[string]bool{
        "-v": true, "--verbose": true, "-w": true, "--watch": true, "--serve": true,
        "--init-templates": true, "--generate-config": true, "--init-site": true, "--force": true, "--shortcodes": true, "--show-urls": true,
        "-e": true, "-p": true,
        "-h": true, "--help": true, "-V": true, "--version": true,
    }
    // Also handle combined -v flags like -vv, -vvv, -vvvv
    for _, a := range args {
        if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
            // short cluster
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                continue
            }
            if strings.HasPrefix(a, "-v") {
                ok := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        ok = false
                        break
                    }
                }
                if ok {
                    continue
                }
            }
            // check if it's like -t value? but -t is known
            // unknown short
            if _, ok := boolFlags[a]; ok {
                continue
            }
            if _, ok := knownWithValue[a]; ok {
                continue
            }
            // If argument looks like negative number? not needed
            // Unknown argument
            fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n", a, a, a)
            os.Exit(2)
        } else if strings.HasPrefix(a, "--") {
            // long flag, may have = value
            base := a
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
            }
            if _, ok := boolFlags[base]; ok {
                continue
            }
            if _, ok := knownWithValue[base]; ok {
                continue
            }
            // also check for --verbose? already bool
            fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n", a, a, a)
            os.Exit(2)
        }
    }
    // Check requires and missing values
    has := func(flag string) bool {
        for _, a := range args {
            if a == flag {
                return true
            }
            if strings.HasPrefix(a, flag+"=") {
                return true
            }
        }
        return false
    }
    getValue := func(flag string) (string, bool) {
        for i, a := range args {
            if a == flag {
                if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
                    return args[i+1], true
                } else if i+1 < len(args) && strings.HasPrefix(args[i+1], "-") {
                    // next is another flag, so missing value
                    return "", false
                } else {
                    return "", false
                }
            }
            if strings.HasPrefix(a, flag+"=") {
                return strings.SplitN(a, "=", 2)[1], true
            }
        }
        return "", false
    }
    // Check missing values for flags that require value
    for _, flag := range []string{"--start-theme", "--set-theme", "--new", "--bind", "--config", "-t", "--name", "--tagline", "--url", "--https", "--footer", "--language", "--pagination", "--enable-search", "--enable-related-content", "--content-path", "--templates-path", "--static-path", "--media-path", "--default-date-format", "--colorscheme", "--toc", "--json-feed", "--show-next-prev-links", "--publish-md", "--source-repository", "--image-provider", "--theme", "--build-sitemap", "--publish-urls-json", "--enable-shortcodes", "--shortcode-pattern", "--skip-image-resize"} {
        if has(flag) {
            if flag == "-t" {
                // -t requires --new
                // will check later
            }
            _, ok := getValue(flag)
            if !ok {
                // need to check if flag present but value missing
                // For clap, error is "a value is required for '--flag <VALUE>' but none was supplied"
                var display string
                switch flag {
                case "--start-theme":
                    display = "--start-theme <START_THEME>"
                case "--set-theme":
                    display = "--set-theme <SET_THEME>"
                case "--new":
                    display = "--new <NEW>"
                case "--bind":
                    display = "--bind <BIND>"
                case "--config":
                    display = "--config <CONFIG>"
                case "-t":
                    display = "-t <TAGS>"
                case "--name":
                    display = "--name <NAME>"
                case "--tagline":
                    display = "--tagline <TAGLINE>"
                case "--url":
                    display = "--url <URL>"
                case "--https":
                    display = "--https <HTTPS>"
                case "--footer":
                    display = "--footer <FOOTER>"
                case "--language":
                    display = "--language <LANGUAGE>"
                case "--pagination":
                    display = "--pagination <PAGINATION>"
                case "--enable-search":
                    display = "--enable-search <ENABLE_SEARCH>"
                case "--enable-related-content":
                    display = "--enable-related-content <ENABLE_RELATED_CONTENT>"
                case "--content-path":
                    display = "--content-path <CONTENT_PATH>"
                case "--templates-path":
                    display = "--templates-path <TEMPLATES_PATH>"
                case "--static-path":
                    display = "--static-path <STATIC_PATH>"
                case "--media-path":
                    display = "--media-path <MEDIA_PATH>"
                case "--default-date-format":
                    display = "--default-date-format <DEFAULT_DATE_FORMAT>"
                case "--colorscheme":
                    display = "--colorscheme <COLORSCHEME>"
                case "--toc":
                    display = "--toc <TOC>"
                case "--json-feed":
                    display = "--json-feed <JSON_FEED>"
                case "--show-next-prev-links":
                    display = "--show-next-prev-links <SHOW_NEXT_PREV_LINKS>"
                case "--publish-md":
                    display = "--publish-md <PUBLISH_MD>"
                case "--source-repository":
                    display = "--source-repository <SOURCE_REPOSITORY>"
                case "--image-provider":
                    display = "--image-provider <IMAGE_PROVIDER>"
                case "--theme":
                    display = "--theme <THEME>"
                case "--build-sitemap":
                    display = "--build-sitemap <BUILD_SITEMAP>"
                case "--publish-urls-json":
                    display = "--publish-urls-json <PUBLISH_URLS_JSON>"
                case "--enable-shortcodes":
                    display = "--enable-shortcodes <ENABLE_SHORTCODES>"
                case "--shortcode-pattern":
                    display = "--shortcode-pattern <SHORTCODE_PATTERN>"
                case "--skip-image-resize":
                    display = "--skip-image-resize <SKIP_IMAGE_RESIZE>"
                default:
                    display = flag
                }
                fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", display)
                os.Exit(2)
            }
        }
    }
    // Check requires: --bind requires --serve
    if has("--bind") && !has("--serve") {
        // Determine if INPUT_FOLDER present later, but for error message, clap checks requires first
        // We need to determine positionals
        positionals := getPositionals(args, knownWithValue, boolFlags)
        if len(positionals) == 0 {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --serve\n  <INPUT_FOLDER>\n\nUsage: executable --serve --bind <BIND> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        } else {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --serve\n\nUsage: executable --serve --bind <BIND> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
    }
    // -e, -p, -t require --new
    if has("-e") && !has("--new") {
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --new <NEW>\n  <INPUT_FOLDER>\n\nUsage: executable --new <NEW> -e <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }
    if has("-p") && !has("--new") {
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --new <NEW>\n  <INPUT_FOLDER>\n\nUsage: executable --new <NEW> -p <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }
    if has("-t") && !has("--new") {
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --new <NEW>\n  <INPUT_FOLDER>\n\nUsage: executable --new <NEW> -t <TAGS> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }
    // Determine positionals (input and output)
    positionals := getPositionals(args, knownWithValue, boolFlags)
    // Handle commands that don't require input folder existence but still need positional for usage
    // Check for missing INPUT_FOLDER
    isHelp := false
    for _, a := range args {
        if a == "--help" || a == "-h" || a == "--version" || a == "-V" {
            isHelp = true
        }
    }
    if isHelp {
        // already handled
    }
    // If no positionals, error
    if len(positionals) == 0 {
        // Determine which usage to show based on flags
        if has("--shortcodes") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --shortcodes <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--generate-config") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --generate-config <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--init-site") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --init-site <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--init-templates") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --init-templates <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--start-theme") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --start-theme <START_THEME> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--set-theme") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --set-theme <SET_THEME> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--new") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --new <NEW> <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        if has("--show-urls") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --show-urls <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
        }
        // default
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }

    inputFolder := positionals[0]
    outputFolder := ""
    if len(positionals) > 1 {
        outputFolder = positionals[1]
    } else {
        // default output is input/site
        outputFolder = filepath.Join(inputFolder, "site")
    }

    // Dispatch commands
    if has("--generate-config") {
        handleGenerateConfig(inputFolder)
        return
    }
    if has("--init-site") {
        handleInitSite(inputFolder)
        return
    }
    if has("--init-templates") {
        handleInitTemplates(inputFolder)
        return
    }
    if has("--start-theme") {
        themeName, _ := getValue("--start-theme")
        handleStartTheme(themeName, inputFolder)
        return
    }
    if has("--set-theme") {
        themePath, _ := getValue("--set-theme")
        handleSetTheme(themePath, inputFolder)
        return
    }
    if has("--new") {
        title, _ := getValue("--new")
        hasE := has("-e")
        hasP := has("-p")
        tags := ""
        if has("-t") {
            tags, _ = getValue("-t")
        }
        handleNew(title, hasE, hasP, tags, inputFolder)
        return
    }
    if has("--shortcodes") {
        handleShortcodes(inputFolder, args)
        return
    }
    if has("--show-urls") {
        handleShowUrls(inputFolder, args)
        return
    }
    // Otherwise site generation (with possible --serve, --watch)
    handleSiteGeneration(inputFolder, outputFolder, args)
}

func getPositionals(args []string, knownWithValue map[string]bool, boolFlags map[string]bool) []string {
    var pos []string
    i := 0
    for i < len(args) {
        a := args[i]
        if a == "--" {
            // rest are positionals
            for _, rest := range args[i+1:] {
                pos = append(pos, rest)
            }
            break
        }
        if strings.HasPrefix(a, "--") {
            base := a
            val := ""
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
                val = parts[1]
                // has value via =, no need to consume next
                _ = val
            } else {
                if _, ok := knownWithValue[base]; ok {
                    // consume next if exists and not flag
                    if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
                        i++
                    } else if i+1 < len(args) && strings.HasPrefix(args[i+1], "-") {
                        // missing value, but we already handled error earlier, skip
                    }
                }
            }
            i++
            continue
        } else if strings.HasPrefix(a, "-") && len(a) > 1 {
            // short flag cluster
            // Check if it's -v, -vv etc handled as bool
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                if a == "-c" || a == "-t" {
                    // these take value
                    if i+1 < len(args) {
                        i += 2
                        continue
                    }
                }
                i++
                continue
            }
            if strings.HasPrefix(a, "-v") {
                // check all v
                allV := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        allV = false
                        break
                    }
                }
                if allV {
                    i++
                    continue
                }
            }
            // unknown short, treat as positional? but already error
            i++
            continue
        } else {
            pos = append(pos, a)
            i++
        }
    }
    return pos
}

