        desc = fmt.Sprintf("%v", v)
    }
    // Check input folder marmite.yaml exists? Create new with theme
    configPath := filepath.Join(inputFolder, "marmite.yaml")
    // If exists, update theme line, else create new
    content := defaultConfig
    if _, err := os.Stat(configPath); err == nil {
        b, _ := os.ReadFile(configPath)
        content = string(b)
        // replace theme: null or existing with new value
        re := regexp.MustCompile(`(?m)^theme:.*$`)
        if re.MatchString(content) {
            content = re.ReplaceAllString(content, "theme: "+themePath)
        } else {
            content += "\ntheme: " + themePath + "\n"
        }
    } else {
        // create new config with theme path
        content = strings.Replace(content, "theme: null", "theme: "+themePath, 1)
    }
    _ = os.WriteFile(configPath, []byte(content), 0644)
