func handleSiteGeneration(inputFolder, outputFolder string, args []string) {
    verbose := 0
    for _, a := range args {
        if a == "-v" || a == "--verbose" {
            verbose = 1
        }
        if a == "-vv" {
            verbose = 2
        }
        if a == "-vvv" {
            verbose = 3
        }
        if a == "-vvvv" {
            verbose = 4
        }
        if strings.HasPrefix(a, "-v") {
            cnt := 0
            for _, ch := range a {
                if ch == 'v' {
                    cnt++
                }
            }
            if cnt > verbose {
                verbose = cnt
            }
        }
    }
    // Check input exists
    if _, err := os.Stat(inputFolder); err != nil {
        logError("Input folder does not exist: \"%s\"", inputFolder)
        os.Exit(1)
    }
    start := time.Now()
    cfg := loadSiteConfig(inputFolder, args, verbose)
    // Process galleries log
    galleryPath := filepath.Join(inputFolder, cfg.ContentPath, "media", "gallery")
    if cfg.ContentPath == "content" {
        galleryPath = filepath.Join(inputFolder, "content", "media", "gallery")
        // But if content folder doesn't exist, use input/media/gallery ?
        // We'll just check both
    }
    if _, err := os.Stat(galleryPath); err != nil {
        if verbose >= 1 {
            logInfoGallery("Processing galleries from: %s", galleryPath)
            logInfoGallery("Gallery directory does not exist: %s", galleryPath)
        }
    } else {
        if verbose >= 1 {
            logInfoGallery("Processing galleries from: %s", galleryPath)
        }
    }
    // Generate site
    if err := os.MkdirAll(outputFolder, 0755); err != nil {
        logError("Failed to create output folder: %v", err)
        os.Exit(1)
    }
    // Generate static
    generateStatic(outputFolder, inputFolder, cfg, verbose)
    // Load contents
    contents := loadContents(inputFolder, cfg)
    // Generate content pages and lists
    generateSitePages(contents, cfg, inputFolder, outputFolder, verbose)
    // Generate sitemap, urls.json, marmite.json
    generateUrlsAndSitemap(contents, cfg, outputFolder, verbose)
    // Generate marmite.json
    generateMarmiteJson(contents, cfg, outputFolder, start, verbose)
    // Copy media
    copyMedia(inputFolder, cfg, outputFolder, verbose)
    // Copy static custom? Already handled
    // Log site generated
    if verbose >= 1 {
        logInfoSite("Site generated at: %s/", outputFolder)
    } else {
        // For non-verbose, do not log? But original for site generation without verbose produced no output, so we should not log
        // However for --serve/--watch etc they log?
    }
    // Handle --serve and --watch
    hasServe := false
    hasWatch := false
    bind := "0.0.0.0:8000"
    for i, a := range args {
        if a == "--serve" {
            hasServe = true
        }
        if a == "--watch" || a == "-w" {
            hasWatch = true
        }
        if a == "--bind" && i+1 < len(args) {
            bind = args[i+1]
        }
        if strings.HasPrefix(a, "--bind=") {
            bind = strings.SplitN(a, "=", 2)[1]
        }
    }
    if hasServe {
        // Generate already done, now serve
        if verbose >= 1 {
            ts := time.Now().UTC().Format("2006-01-02T15:04:05Z")
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite] Starting built-in HTTP server...\n", ts)
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite::server] Server started at http://%s/ - Type ^C to stop.\n", ts, bind)
        } else {
            // Even without verbose, serve logs? In earlier test with --serve and no -v, it still logged starting server after generation? Let's check: we ran timeout 2 ./executable --serve /tmp/new_site and saw logs even without -v: It logged config loaded from defaults at INFO even without -v? Wait that test used --serve without -v but still logged INFO for site generation? Let's see: earlier timeout 2 ./executable --serve gave INFO logs even without -v? The output showed INFO logs for site generation. So maybe --serve always enables verbose?
            // For simplicity, always log serve start
            ts := time.Now().UTC().Format("2006-01-02T15:04:05Z")
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite] Starting built-in HTTP server...\n", ts)
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite::server] Server started at http://%s/ - Type ^C to stop.\n", ts, bind)
        }
