            // Even without verbose, watch logs? earlier with --watch and no -v, it logged watching
            ts := time.Now().UTC().Format("2006-01-02T15:04:05Z")
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite::site] Watching for changes in folder: %s\n", ts, inputFolder)
        }
        // Watch loop (simple poll)
        for {
            time.Sleep(2 * time.Second)
            // naive: regenerate if any file changed? For now just sleep
        }
    }
}

