func loadContents(inputFolder string, cfg SiteConfig) []*Content {
    var contents []*Content
    var contentDir string
    cand := filepath.Join(inputFolder, cfg.ContentPath)
    if _, err := os.Stat(cand); err == nil {
        contentDir = cand
    } else {
        contentDir = inputFolder
    }
    // Walk for md files
    filepath.Walk(contentDir, func(path string, info fs.FileInfo, err error) error {
        if err != nil {
            return nil
        }
        if info.IsDir() {
            return nil
        }
        if !strings.HasSuffix(strings.ToLower(info.Name()), ".md") {
            return nil
        }
        // Skip hidden
        if strings.HasPrefix(info.Name(), ".") {
            return nil
        }
        // Skip underscore files except _404.md
        if strings.HasPrefix(info.Name(), "_") && info.Name() != "_404.md" {
            // But still need to read _markdown_header/footer etc for injection? We'll just skip as page
            return nil
        }
        c, err := parseContentFile(path)
        if err != nil {
            // log error but continue
            fmt.Fprintf(os.Stderr, "[%s ERROR marmite::site] Failed to process content: \"%s\"\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), err.Error())
            return nil
        }
        // Handle index.md special: we treat as fragment for index page, not as content? But for now add as page? Let's check if filename is index.md
        if strings.ToLower(info.Name()) == "index.md" {
            // treat as fragment: don't add as page, but could store for index title
            // We'll still add but with slug index, but later list generation will handle
            // To avoid duplicate index.html, we will not add index.md as page if we want list index
            // Original treated index.md as providing index page content, not as separate page
            // So skip adding to contents, but store its title for later? For simplicity, skip
            return nil
        }
        contents = append(contents, c)
        return nil
    })
    return contents
}

func generateSitePages(contents []*Content, cfg SiteConfig, inputFolder, outputFolder string, verbose int) {
    // Sort contents: posts by date desc, pages by slug asc?
    var posts []*Content
    var pages []*Content
    for _, c := range contents {
        if c.IsPost {
            posts = append(posts, c)
        } else {
            pages = append(pages, c)
        }
    }
    sort.Slice(posts, func(i, j int) bool {
        if posts[i].Date == nil || posts[j].Date == nil {
            return posts[i].Title < posts[j].Title
        }
        return posts[i].Date.After(*posts[j].Date)
    })
    sort.Slice(pages, func(i, j int) bool {
        return strings.ToLower(pages[i].Slug) < strings.ToLower(pages[j].Slug)
    })
    // Read fragments for injection: _markdown_header/footer, _hero, _announce, etc.
    var mdHeader, mdFooter string
    contentDir := filepath.Join(inputFolder, cfg.ContentPath)
    if _, err := os.Stat(contentDir); err != nil {
        contentDir = inputFolder
    }
    if data, err := os.ReadFile(filepath.Join(contentDir, "_markdown_header.md")); err == nil {
        mdHeader = string(data)
    }
    if data, err := os.ReadFile(filepath.Join(contentDir, "_markdown_footer.md")); err == nil {
        mdFooter = string(data)
    }
    // For each content, generate html file
    for _, c := range contents {
        // Inject header/footer into html? Original injects header/footer markdown into every content's html
        html := c.HTML
        if mdHeader != "" {
            // render mdHeader as html and prepend?
            hdrHTML := markdownToHTML(mdHeader)
            html = hdrHTML + "\n" + html
            if c.Description == "" {
                // also affect description? not needed
            }
        }
        if mdFooter != "" {
            ftrHTML := markdownToHTML(mdFooter)
            html = html + "\n" + ftrHTML
        }
        // Generate page
        outPath := filepath.Join(outputFolder, c.Slug+".html")
        // Ensure dir exists (slug may contain subdir? but we treat as flat)
        // If slug contains "/" replace? but we keep as is, create dirs if needed
        if strings.Contains(c.Slug, "/") {
            os.MkdirAll(filepath.Dir(outPath), 0755)
        }
        pageHTML := generateContentHTML(c, html, cfg, inputFolder)
        _ = os.WriteFile(outPath, []byte(pageHTML), 0644)
        if verbose >= 1 {
            logInfoSite("Generated %s", outPath)
        }
        // Also handle publish-md if enabled? Not needed
    }
    // Generate list pages
    // 404
    generate404(outputFolder, cfg, contentDir, verbose)
    // index (list of posts)
    generateListPage(filepath.Join(outputFolder, "index.html"), "Home", posts, cfg, 1, 1, verbose, "index.html", contents)
    // pagination for index
    paginateList(posts, cfg.Pagination, outputFolder, "index", verbose, cfg)
    // pages list
    generateListPage(filepath.Join(outputFolder, "pages.html"), cfgFooterPagesTitle(cfg), pages, cfg, 1, 1, verbose, "pages.html", contents)
    paginateList(pages, cfg.Pagination, outputFolder, "pages", verbose, cfg)
    // tags
    tagsMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, t := range p.Tags {
            tagsMap[t] = append(tagsMap[t], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "tags.html"), "Tags", tagsMap, cfg, verbose, "tag")
    for tag, list := range tagsMap {
        slug := "tag-" + slugify(tag)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts tagged with '"+tag+"'", list, cfg, 1, 1, verbose, slug+".html", contents)
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        // rss
        generateRSS(filepath.Join(outputFolder, slug+".rss"), tag, list, cfg)
    }
    // authors
    authorsMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, a := range p.Authors {
            authorsMap[a] = append(authorsMap[a], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "authors.html"), "Authors", authorsMap, cfg, verbose, "author")
    for author, list := range authorsMap {
        slug := "author-" + slugify(author)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts by "+author, list, cfg, 1, 1, verbose, slug+".html", contents)
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), author, list, cfg)
    }
    // series
    seriesMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Series != "" {
            seriesMap[p.Series] = append(seriesMap[p.Series], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "series.html"), "Series", seriesMap, cfg, verbose, "series")
    for s, list := range seriesMap {
        slug := "series-" + slugify(s)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+s+"' series", list, cfg, 1, 1, verbose, slug+".html", contents)
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), s, list, cfg)
    }
    // streams
    streamsMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Stream != "" {
            streamsMap[p.Stream] = append(streamsMap[p.Stream], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "streams.html"), "Streams", streamsMap, cfg, verbose, "stream")
    for s, list := range streamsMap {
        slug := slugify(s)
        // For stream, slug is just slugified stream (not prefix)
        // But original uses stream slug as is? For "mystream" -> "mystream", for "my stream" -> "my-stream"
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+s+"'", list, cfg, 1, 1, verbose, slug+".html", contents)
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), s, list, cfg)
    }
    // archives
    archivesMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Date != nil {
            year := fmt.Sprintf("%d", p.Date.Year())
            archivesMap[year] = append(archivesMap[year], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "archive.html"), "Archive", archivesMap, cfg, verbose, "archive")
    for year, list := range archivesMap {
        slug := "archive-" + year
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+year+"'", list, cfg, 1, 1, verbose, slug+".html", contents)
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), year, list, cfg)
    }
    // Also generate archive year pagination etc already
    // Generate feeds for index
    if len(posts) > 0 {
        generateRSS(filepath.Join(outputFolder, "index.rss"), "index", posts, cfg)
        generateRSS(filepath.Join(outputFolder, "archive-2023.rss"), "archive", posts, cfg) // simplified
    }
}

