func paginateList(items []*Content, pagination int, outputFolder, base string, verbose int, cfg SiteConfig) {
    if pagination <= 0 {
        pagination = 10
    }
    total := len(items)
    if total == 0 {
        return
    }
    pages := (total + pagination - 1) / pagination
    for i := 1; i <= pages; i++ {
        start := (i - 1) * pagination
        end := start + pagination
        if end > total {
            end = total
        }
        slice := items[start:end]
        filename := fmt.Sprintf("%s-%d.html", base, i)
        outPath := filepath.Join(outputFolder, filename)
        // For base "index", pagination files are index-1.html etc.
        // For base "pages", pages-1.html etc.
        title := ""
        if base == "index" {
            title = "Home"
        } else if base == "pages" {
            title = "Pages"
        } else {
            title = base
        }
        generateListPage(outPath, title, slice, cfg, i, pages, verbose, filename, nil)
    }
}

func generateListPage(outPath, title string, items []*Content, cfg SiteConfig, current, total int, verbose int, currentPage string, allContents []*Content) {
    // Simple HTML list
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"color-scheme\" content=\"light dark\" />\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:title\" content=\"%s\">\n", htmlEscape(title)))
    sb.WriteString("    <meta property=\"og:description\" content=\"\">\n")
    sb.WriteString("    <meta property=\"og:type\" content=\"website\">\n")
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:site_name\" content=\"%s\">\n", htmlEscape(cfg.Name)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString("<header class=\"header-content\"><nav class=\"header-nav\"><ul class=\"header-name\"><li><hgroup class=\"h-card\"><h2><a href=\"/\" class=\"contrast p-name u-url\">" + htmlEscape(cfg.Name) + "</a></h2></hgroup></li></ul></nav></header>\n")
    sb.WriteString("<section class=\"main-content\">\n")
    if title != "" && currentPage != "index.html" {
        sb.WriteString(fmt.Sprintf("<div class=\"list-title\"><article><strong> %s </strong></article></div>\n", htmlEscape(title)))
    }
    sb.WriteString("<div class=\"content-list h-feed\">\n")
    if len(items) == 0 {
        sb.WriteString("<article class=\"content-list-item left\"><h2 class=\"content-title\">No content found</h2><p class=\"content-excerpt\">Add some markdown content and generate the site. &rarr; <a target=\"_blank\" href=\"https://marmite.blog/getting-started.html\">Getting Started</a></p></article>\n")
    } else {
        for _, c := range items {
            sb.WriteString("<article class=\"content-list-item h-entry\">\n")
            sb.WriteString(fmt.Sprintf("<h2 class=\"p-name\" style=\"display: none;\">%s</h2>\n", htmlEscape(c.Title)))
            sb.WriteString(fmt.Sprintf("<a class=\"u-url\" href=\"/%s.html\" style=\"display: none;\"></a>\n", c.Slug))
            if c.Date != nil {
                sb.WriteString(fmt.Sprintf("<time class=\"dt-published\" datetime=\"%s\" style=\"display: none;\">%s</time>\n", c.Date.Format(time.RFC3339), c.Date.Format("Jan 2, 2006")))
            }
            sb.WriteString(fmt.Sprintf("<div class=\"content-title-wrapper\"><h2 class=\"content-title\"><a href=\"/%s.html\">%s</a></h2></div>\n", c.Slug, htmlEscape(c.Title)))
            sb.WriteString("<p class=\"content-excerpt p-summary\">")
            if c.Description != "" {
                sb.WriteString(htmlEscape(c.Description))
            } else {
                // strip tags from html
                txt := stripTags(c.HTML)
                if len(txt) > 250 {
                    txt = txt[:250] + " ..."
                }
                sb.WriteString(htmlEscape(txt))
            }
            sb.WriteString(fmt.Sprintf(" <a class=\"secondary\" href=\"/%s.html\">read more &rarr;</a></p>\n", c.Slug))
            if c.Date != nil {
                sb.WriteString("<footer class=\"data-tags-footer\">\n")
                sb.WriteString(fmt.Sprintf("<span class=\"content-date\"><a class=\"secondary\" href=\"/%s.html\">%s</a></span>\n", c.Slug, c.Date.Format("Jan 2, 2006")))
                if len(c.Tags) > 0 {
                    sb.WriteString("<ul class=\"content-tags overflow-auto\">\n")
                    for _, t := range c.Tags {
                        slug := "tag-" + slugify(t)
                        sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\" class=\"p-category\">%s</a></li>\n", slug, htmlEscape(t)))
                    }
                    sb.WriteString("</ul>\n")
                }
                sb.WriteString("</footer>\n")
            }
            sb.WriteString("</article>\n")
        }
    }
    if total > 1 {
        sb.WriteString("<div class=\"pagination\"><nav><ul>")
        if current > 1 {
            prev := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current-1)
            // Simplified
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&larr;</strong></a></li>", prev))
        }
        sb.WriteString(fmt.Sprintf("<li><small>%d/%d</small></li>", current, total))
        if current < total {
            next := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current+1)
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&rarr;</strong></a></li>", next))
        }
        sb.WriteString("</ul></nav></div>")
    }
    sb.WriteString("</div>\n</section>\n")
    sb.WriteString(fmt.Sprintf("<footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func stripTags(html string) string {
    re := regexp.MustCompile(`<[^>]*>`)
    return re.ReplaceAllString(html, "")
}

func generateGroupPage(outPath, title string, groupMap map[string][]*Content, cfg SiteConfig, verbose int, kind string) {
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"color-scheme\" content=\"light dark\" />\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(title), htmlEscape(cfg.Name)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString(fmt.Sprintf("<div class=\"list-title\"><article><strong> %s </strong></article></div>\n", htmlEscape(title)))
    sb.WriteString("<article class=\"group-details h-feed\">\n")
    sb.WriteString(fmt.Sprintf("<h1 class=\"p-name\" style=\"display: none;\">%s</h1>\n", htmlEscape(title)))
    // list groups
    if len(groupMap) == 0 {
        // empty
    } else {
        // sort keys
        keys := make([]string, 0, len(groupMap))
        for k := range groupMap {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            // For display, link to group's page
            var slug string
            if kind == "stream" {
                slug = slugify(k)
            } else {
                slug = kind + "-" + slugify(k)
            }
            sb.WriteString(fmt.Sprintf("<details><summary>%s (%d)</summary><ul>", htmlEscape(k), len(groupMap[k])))
            for _, c := range groupMap[k] {
                sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">%s</a></li>", c.Slug, htmlEscape(c.Title)))
            }
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">more &rarr;</a></li>", slug))
            sb.WriteString("</ul></details>")
        }
    }
    sb.WriteString("</article>\n</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

