    sb.WriteString("</head>\n")
    sb.WriteString("<body>\n")
    sb.WriteString("    <main class=\"container\">\n")
    sb.WriteString("        <header class=\"header-content\"><nav class=\"header-nav\"><ul class=\"header-name\"><li><hgroup class=\"h-card\"><h2><a href=\"/\" class=\"contrast p-name u-url\">" + htmlEscape(cfg.Name) + "</a></h2></hgroup></li></ul></nav></header>\n")
    sb.WriteString("        <section class=\"main-content\">\n")
    sb.WriteString("<article class=\"h-entry\">\n")
    sb.WriteString(fmt.Sprintf("  <data class=\"p-name\" value=\"%s\"></data>\n", htmlEscape(c.Title)))
    sb.WriteString(fmt.Sprintf("  <a class=\"u-url\" href=\"/%s.html\" style=\"display: none;\"></a>\n", c.Slug))
    if c.Date != nil {
        sb.WriteString(fmt.Sprintf("  <time class=\"dt-published\" datetime=\"%s\" style=\"display: none;\">%s</time>\n", c.Date.Format(time.RFC3339), c.Date.Format("Jan 2, 2006")))
    }
    sb.WriteString("<div class=\"content-title\" id=\"title\">\n")
    sb.WriteString(fmt.Sprintf("    <h1>%s</h1> \n", htmlEscape(c.Title)))
    sb.WriteString("<span class=\"content-date\"><small></small></span>\n")
    sb.WriteString("</div>\n")
    sb.WriteString(fmt.Sprintf("  <div class=\"content-html e-content\">%s</div>\n", htmlContent))
    sb.WriteString("</article>\n")
    sb.WriteString("        </section>\n")
    sb.WriteString(fmt.Sprintf("        <footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("    </main>\n")
    sb.WriteString("    <script src=\"/static/marmite.js\"></script>\n")
    sb.WriteString("    <script src=\"/static/custom.js\"></script>\n")
    sb.WriteString("<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/highlight.min.js\"></script><script>hljs.highlightAll();</script>\n")
    sb.WriteString("</body>\n</html>\n")
    return sb.String()
}

func generateUrlsAndSitemap(contents []*Content, cfg SiteConfig, outputFolder string, verbose int) {
    urls := generateUrls(contents, cfg)
    if cfg.PublishUrlsJson {
        data, _ := json.MarshalIndent(urls, "", "  ")
        outPath := filepath.Join(outputFolder, "urls.json")
        _ = os.WriteFile(outPath, data, 0644)
        if verbose >= 1 {
            logInfoSite("Generated urls.json")
        }
    }
    if cfg.BuildSitemap {
        // collect all urls for sitemap
        var sitemapUrls []string
        // helper to add prefix if cfg.URL set
        prefix := ""
        if cfg.URL != "" {
            prefix = strings.TrimSuffix(cfg.URL, "/")
        }
        add := func(u string) {
            if prefix != "" {
                // make absolute
                if strings.HasPrefix(u, "/") {
                    sitemapUrls = append(sitemapUrls, prefix+u)
                } else {
                    sitemapUrls = append(sitemapUrls, prefix+"/"+u)
                }
            } else {
                sitemapUrls = append(sitemapUrls, u)
            }
        }
        for _, u := range urls.Posts {
            add(u)
        }
        for _, u := range urls.Pages {
            add(u)
        }
        for _, u := range urls.Tags {
            add(u)
        }
        for _, u := range urls.Authors {
            add(u)
        }
        for _, u := range urls.Series {
            add(u)
        }
        for _, u := range urls.Streams {
            add(u)
        }
        for _, u := range urls.Archives {
            add(u)
        }
        for _, u := range urls.Feeds {
            add(u)
        }
        for _, u := range urls.Pagination {
            add(u)
        }
        for _, u := range urls.Misc {
            add(u)
        }
        // Generate sitemap.xml
        var sb strings.Builder
        sb.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
        sb.WriteString(`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">` + "\n")
        for _, u := range sitemapUrls {
            sb.WriteString("  <url>\n")
            sb.WriteString(fmt.Sprintf("    <loc>%s</loc>\n", htmlEscape(u)))
            sb.WriteString("  </url>\n")
        }
        sb.WriteString(`</urlset>`)
        outPath := filepath.Join(outputFolder, "sitemap.xml")
        _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
        if verbose >= 1 {
            logInfoSite("Generated sitemap.xml with %d URLs", len(sitemapUrls))
        }
    }
}

type Urls struct {
    Posts        []string `json:"posts"`
    Pages        []string `json:"pages"`
    Tags         []string `json:"tags"`
    Authors      []string `json:"authors"`
    Series       []string `json:"series"`
    Streams      []string `json:"streams"`
    Archives     []string `json:"archives"`
    Feeds        []string `json:"feeds"`
    Pagination   []string `json:"pagination"`
    FileMappings []string `json:"file_mappings"`
    Misc         []string `json:"misc"`
    Summary      Summary `json:"summary"`
    Meta         Meta    `json:"-"`
}

type Summary struct {
    Posts        int `json:"posts"`
    Pages        int `json:"pages"`
    Tags         int `json:"tags"`
    Authors      int `json:"authors"`
    Series       int `json:"series"`
    Streams      int `json:"streams"`
    Archives     int `json:"archives"`
    Feeds        int `json:"feeds"`
    Pagination   int `json:"pagination"`
    FileMappings int `json:"file_mappings"`
    Misc         int `json:"misc"`
    Total        int `json:"total"`
    Meta         MetaSummary `json:"meta"`
}
type Meta struct {
    URL           string `json:"url"`
    AbsoluteUrls bool   `json:"absolute_urls"`
}
type MetaSummary struct {
    URL           string `json:"url"`
    AbsoluteUrls bool   `json:"absolute_urls"`
}

func generateUrls(contents []*Content, cfg SiteConfig) map[string]interface{} {
    var posts []*Content
    var pages []*Content
    for _, c := range contents {
        if c.IsPost {
            posts = append(posts, c)
        } else {
            pages = append(pages, c)
        }
    }
    // tags etc only from posts
    tagsMap := make(map[string][]*Content)
    authorsMap := make(map[string][]*Content)
    seriesMap := make(map[string][]*Content)
    streamsMap := make(map[string][]*Content)
    archivesMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, t := range p.Tags {
            tagsMap[t] = append(tagsMap[t], p)
        }
        for _, a := range p.Authors {
            authorsMap[a] = append(authorsMap[a], p)
        }
        if p.Series != "" {
            seriesMap[p.Series] = append(seriesMap[p.Series], p)
        }
        if p.Stream != "" {
            streamsMap[p.Stream] = append(streamsMap[p.Stream], p)
        }
        if p.Date != nil {
            year := fmt.Sprintf("%d", p.Date.Year())
            archivesMap[year] = append(archivesMap[year], p)
        }
    }
    pagination := cfg.Pagination
    if pagination <= 0 {
        pagination = 10
    }
    // Build slices
    var postsUrls []string
    for _, p := range posts {
        u := "/" + p.Slug + ".html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        postsUrls = append(postsUrls, u)
    }
    var pagesUrls []string
    for _, p := range pages {
        u := "/" + p.Slug + ".html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        pagesUrls = append(pagesUrls, u)
    }
    if len(pages) > 0 {
        u := "/pages.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        pagesUrls = append(pagesUrls, u)
    }
    var tagsUrls []string
    if len(tagsMap) > 0 {
        for tag := range tagsMap {
            slug := "tag-" + slugify(tag)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            tagsUrls = append(tagsUrls, u)
        }
        sort.Strings(tagsUrls)
        u := "/tags.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        tagsUrls = append(tagsUrls, u)
        sort.Strings(tagsUrls) // but original tags order? For minimal, tags was empty, but for post with tag, tagsUrls had tag-rust then tags.html sorted? Let's sort to be deterministic
    }
    var authorsUrls []string
    if len(authorsMap) > 0 {
        for a := range authorsMap {
            slug := "author-" + slugify(a)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            authorsUrls = append(authorsUrls, u)
        }
        sort.Strings(authorsUrls)
        u := "/authors.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        authorsUrls = append(authorsUrls, u)
        sort.Strings(authorsUrls)
    }
    var seriesUrls []string
    if len(seriesMap) > 0 {
        for s := range seriesMap {
            slug := "series-" + slugify(s)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            seriesUrls = append(seriesUrls, u)
        }
        sort.Strings(seriesUrls)
        u := "/series.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        seriesUrls = append(seriesUrls, u)
        sort.Strings(seriesUrls)
    }
    var streamsUrls []string
    if len(streamsMap) > 0 {
        for s := range streamsMap {
            slug := slugify(s)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            streamsUrls = append(streamsUrls, u)
        }
        sort.Strings(streamsUrls)
        u := "/streams.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        streamsUrls = append(streamsUrls, u)
        sort.Strings(streamsUrls)
    }
    var archivesUrls []string
    if len(archivesMap) > 0 {
        for year := range archivesMap {
            slug := "archive-" + year
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            archivesUrls = append(archivesUrls, u)
        }
        sort.Strings(archivesUrls)
        u := "/archive.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        archivesUrls = append(archivesUrls, u)
        sort.Strings(archivesUrls)
    }
    var feedsUrls []string
    if len(posts) > 0 {
        // index.rss
        u := "/index.rss"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        feedsUrls = append(feedsUrls, u)
        // for each tag
        for tag := range tagsMap {
            slug := "tag-" + slugify(tag)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for a := range authorsMap {
            slug := "author-" + slugify(a)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for s := range seriesMap {
            slug := "series-" + slugify(s)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for s := range streamsMap {
            slug := slugify(s)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for year := range archivesMap {
            slug := "archive-" + year
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        sort.Strings(feedsUrls)
    }
    var paginationUrls []string
    // pages pagination
    if len(pages) > 0 {
        cnt := (len(pages) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            u := fmt.Sprintf("/pages-%d.html", i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    // tags pagination
    for tag, lst := range tagsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "tag-" + slugify(tag)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for a, lst := range authorsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "author-" + slugify(a)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for s, lst := range seriesMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "series-" + slugify(s)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for s, lst := range streamsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := slugify(s)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for year, lst := range archivesMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "archive-" + year
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    // index pagination
    if len(posts) > 0 {
        cnt := (len(posts) + pagination - 1) / pagination
        // The original for index pagination seems to start at 1? But they have index-1.html etc, not index.html itself
        // For posts pagination, they generate index-1, index-2 etc
        // Only if needed? For 1 post, no index pagination? In post case with 1 post, there was no index pagination (pagination had tag and archive only)
        // So maybe they generate index pagination only if posts > pagination?
        // But for 12 posts with pagination 10, they had 2 pagination files
        // So we generate if cnt > 1? Let's see: count=1 for 1 post gives cnt=1 -> would generate index-1.html, but they didn't for 1 post case.
        // So maybe threshold is >1
        if cnt > 1 {
            for i := 1; i <= cnt; i++ {
                u := fmt.Sprintf("/index-%d.html", i)
                if cfg.URL != "" {
                    u = strings.TrimSuffix(cfg.URL, "/") + u
                }
                paginationUrls = append(paginationUrls, u)
            }
        }
    }
    sort.Strings(paginationUrls)
    var miscUrls []string
    u := "/index.html"
    if cfg.URL != "" {
        u = strings.TrimSuffix(cfg.URL, "/") + u
    }
    miscUrls = []string{u}

    // Build summary
    total := len(postsUrls) + len(pagesUrls) + len(tagsUrls) + len(authorsUrls) + len(seriesUrls) + len(streamsUrls) + len(archivesUrls) + len(feedsUrls) + len(paginationUrls) + len(miscUrls)
    summary := map[string]interface{}{
        "posts":        len(postsUrls) - 0, // posts count? Actually summary posts is count of posts (number of post files), not urls? In urls, posts urls count equals number of posts
        // For minimal pages, posts 0, pages 2 (including pages.html), tags 0 etc
        // So summary counts match length of each slice
        "pages":        len(pagesUrls),
        "tags":         len(tagsUrls),
        "authors":      len(authorsUrls),
        "series":       len(seriesUrls),
        "streams":      len(streamsUrls),
        "archives":     len(archivesUrls),
        "feeds":        len(feedsUrls),
        "pagination":   len(paginationUrls),
        "file_mappings": 0,
        "misc":         len(miscUrls),
        "total":        total,
        "meta": map[string]interface{}{
            "url":           cfg.URL,
            "absolute_urls": cfg.URL != "",
        },
    }
    // But note original summary posts is number of posts, not postsUrls length? For post case, posts 1, pages 0, etc matching
    // For pages case, posts 0, pages 2 etc.
    // So we set summary posts = len(posts) not len(postsUrls)? But they matched for posts case: posts 1 vs postsUrls len 1, same. For pages case: pagesUrls len 2, summary pages 2, matches.
    // For tags, summary tags is len(tagsUrls)?? For post with tag, tagsUrls len 2 (tag-rust + tags.html), summary tags 2, matches.
    // So we can set as len slices
    summary["posts"] = len(posts)
    // But pages summary is len(pagesUrls)?? For pages case, len(pages)=1 but pagesUrls=2, summary pages 2, so not len(pages)
    // So we keep as len(pagesUrls) for pages, etc.

    // Actually we need to set posts summary as len(posts) (number of posts), not len(postsUrls)?? They are same for posts.
    // We'll set as len(postsUrls) for consistency, but for pages we need len(pagesUrls)
    // For posts, we already set postsUrls = len(posts) (since each post one url), so it's same.
    // So we can just use len slices for all.

    // Adjust summary posts to be len(posts) (not postsUrls) but they are same

    result := map[string]interface{}{
        "posts":        postsUrls,
        "pages":        pagesUrls,
        "tags":         tagsUrls,
        "authors":      authorsUrls,
        "series":       seriesUrls,
        "streams":      streamsUrls,
        "archives":     archivesUrls,
        "feeds":        feedsUrls,
        "pagination":   paginationUrls,
        "file_mappings": []string{},
        "misc":         miscUrls,
        "summary":      summary,
        "meta": map[string]interface{}{
            "url":           cfg.URL,
            "absolute_urls": cfg.URL != "",
        },
    }
    // Ensure nil slices become empty arrays in JSON, not null
    for k, v := range result {
        if arr, ok := v.([]string); ok && arr == nil {
            result[k] = []string{}
        }
    }
    return result
}

func generateMarmiteJson(contents []*Content, cfg SiteConfig, outputFolder string, start time.Time, verbose int) {
    var posts, pages int
    for _, c := range contents {
        if c.IsPost {
            posts++
        } else {
            pages++
        }
    }
    elapsed := time.Since(start).Seconds()
    now := time.Now()
    // Generated_at format: "2026-09-06 02:59:45.630355037 +00:00"
    genAt := now.Format("2006-01-02 15:04:05.000000000 +00:00")
    // timestamp is unix? but original had 1788663585 which is future, but we use now.Unix()
    ts := now.Unix()
    // For compatibility, we could use same as original's future? But use now
    data := map[string]interface{}{
        "marmite_version": "0.2.7",
