            "streams":                  map[string]interface{}{},
            "series":                   map[string]interface{}{},
            "toc":                      false,
            "json_feed":                false,
            "show_next_prev_links":     true,
            "publish_md":               false,
            "source_repository":        nil,
            "image_provider":           nil,
            "markdown_parser":          nil,
            "theme":                    nil,
            "file_mapping":             []string{},
