        "-e": true, "-p": true,
        "-h": true, "--help": true, "-V": true, "--version": true,
    }
    // Also handle combined -v flags like -vv, -vvv, -vvvv
    for _, a := range args {
        if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
            // short cluster
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                continue
            }
            if strings.HasPrefix(a, "-v") {
                ok := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        ok = false
                        break
                    }
                }
                if ok {
                    continue
                }
            }
            // check if it's like -t value? but -t is known
            // unknown short
            if _, ok := boolFlags[a]; ok {
                continue
            }
            if _, ok := knownWithValue[a]; ok {
                continue
            }
            // If argument looks like negative number? not needed
            // Unknown argument
            fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n", a, a, a)
            os.Exit(2)
        } else if strings.HasPrefix(a, "--") {
            // long flag, may have = value
            base := a
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
            }
            if _, ok := boolFlags[base]; ok {
                continue
            }
            if _, ok := knownWithValue[base]; ok {
                continue
            }
            // also check for --verbose? already bool
