        }
    }
    if isHelp {
        // already handled
    }
    // If no positionals, error
    if len(positionals) == 0 {
        // Determine which usage to show based on flags
        if has("--shortcodes") {
            fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable --shortcodes <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n")
            os.Exit(2)
