        return
    }
    // Otherwise site generation (with possible --serve, --watch)
    handleSiteGeneration(inputFolder, outputFolder, args)
}

func getPositionals(args []string, knownWithValue map[string]bool, boolFlags map[string]bool) []string {
    var pos []string
    i := 0
    for i < len(args) {
        a := args[i]
        if a == "--" {
            // rest are positionals
            for _, rest := range args[i+1:] {
                pos = append(pos, rest)
            }
            break
        }
        if strings.HasPrefix(a, "--") {
            base := a
            val := ""
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
                val = parts[1]
                // has value via =, no need to consume next
                _ = val
            } else {
                if _, ok := knownWithValue[base]; ok {
                    // consume next if exists and not flag
                    if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
                        i++
                    } else if i+1 < len(args) && strings.HasPrefix(args[i+1], "-") {
                        // missing value, but we already handled error earlier, skip
                    }
                }
            }
            i++
            continue
        } else if strings.HasPrefix(a, "-") && len(a) > 1 {
            // short flag cluster
            // Check if it's -v, -vv etc handled as bool
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                if a == "-c" || a == "-t" {
                    // these take value
                    if i+1 < len(args) {
                        i += 2
                        continue
                    }
                }
                i++
                continue
            }
            if strings.HasPrefix(a, "-v") {
                // check all v
                allV := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        allV = false
                        break
                    }
                }
                if allV {
                    i++
                    continue
                }
            }
            // unknown short, treat as positional? but already error
            i++
            continue
        } else {
            pos = append(pos, a)
            i++
        }
    }
    return pos
}

