func handleGenerateConfig(inputFolder string) {
    // inputFolder must exist? earlier test showed it must exist else error
    if _, err := os.Stat(inputFolder); err != nil {
        logError("Input folder does not exist: \"%s\"", inputFolder)
        os.Exit(1)
    }
    outPath := filepath.Join(inputFolder, "marmite.yaml")
    err := os.WriteFile(outPath, []byte(defaultConfig), 0644)
    if err != nil {
        logError("Failed to write config: %v", err)
        os.Exit(1)
    }
    // log always
    logInfo("Config file generated: %s", outPath)
}

func handleInitSite(inputFolder string) {
    // Creates inputFolder if not exists, then generates config and sample content
    if err := os.MkdirAll(inputFolder, 0755); err != nil {
        logError("Failed to create input folder: %v", err)
        os.Exit(1)
    }
    // generate config
    outPath := filepath.Join(inputFolder, "marmite.yaml")
    // overwrite existing
    _ = os.WriteFile(outPath, []byte(defaultConfig), 0644)
    logInfo("Config file generated: %s", outPath)
    // create content folder
    contentDir := filepath.Join(inputFolder, "content")
    os.MkdirAll(contentDir, 0755)
    // create media dir
    os.MkdirAll(filepath.Join(contentDir, "media"), 0755)
    // sample files
    files := map[string]string{
        "2026-09-06-welcome.md": "# Welcome to Marmite\n\nThis is your first post!\n\n## Edit this content\n\nedit on `content/{date}-welcome.md`\n\n## Add more content\n\ncreate new markdown files in the `content` folder\n\nuse `marmite --new` to create new content\n\n## Customize your site\n\nedit `marmite.yaml` to change site settings\n\nedit the files starting with `_` in the `content` folder to change the layout\n\nor edit the templates to create a custom layout\n\n## Deploy your site\n\nread more on [marmite documentation](https://marmite.blog)\n",
        "_404.md":              "# Not Found",
        "_announce.md":         "Give us a &star; on [github]",
        "_comments.md":         "##### Comments\n**edit `content/_comments.md` to adjust for your own site/repo**\n\n**remove** the file to disable comments\n\n<script src='https://utteranc.es/client.js'\nrepo='rochacbruno/issue-bin'\nissue-term='pathname'\ntheme='preferred-color-scheme'\ncrossorigin='anonymous'\nasync>\n</script>\n",
        "_hero.md":             "##### Welcome to Marmite\n\nMarmite is a static site generator written in Rust.\nedit `content/_hero.md` to change this content.\nremove the file to disable the hero section.\n",
        "_markdown_footer.md":  "<!-- Content Injected to every content markdown footer -->",
        "_markdown_header.md":  "<!-- Content Injected to every content markdown header -->",
        "_references.md":       "[github]: https://github.com/rochacbruno/marmite",
        "_sidebar.example.md":  "\n    {% set groups = ['tag', 'archive', 'author', 'stream'] %}\n{% for group in groups %}\n\n##### {{group}}s\n\n{% for name, items in group(kind=group) -%}\n- [{{name}}]({{group}}-{{name | slugify}}.html)\n{% endfor %}\n\n{% endfor %}\n    ",
        "about.md":             "# About\n\nHi, edit `about.md` to change this content.\n        ",
    }
    for name, content := range files {
        p := filepath.Join(contentDir, name)
        _ = os.WriteFile(p, []byte(content), 0644)
    }
    // custom files at root
    _ = os.WriteFile(filepath.Join(inputFolder, "custom.css"), []byte("/* Custom CSS */"), 0644)
    _ = os.WriteFile(filepath.Join(inputFolder, "custom.js"), []byte("// Custom JS"), 0644)
    // log
    // use site logger? original uses marmite::site for init-site second log, and marmite::config for first
    // we already logged config
    // now site initialized
    ts := time.Now().UTC().Format("2006-01-02T15:04:05Z")
    fmt.Fprintf(os.Stderr, "[%s INFO  marmite::site] Site initialized in %s\n", ts, inputFolder)
}

