func handleStartTheme(themeName, inputFolder string) {
    if _, err := os.Stat(inputFolder); err != nil {
        logError("Input folder does not exist: \"%s\"", inputFolder)
        os.Exit(1)
    }
    themeDir := filepath.Join(inputFolder, themeName)
    if err := os.MkdirAll(themeDir, 0755); err != nil {
        logError("Failed to create theme directory: %v", err)
        os.Exit(1)
    }
    // create README
    readmePath := filepath.Join(themeDir, "README.md")
    _ = os.WriteFile(readmePath, []byte(themeReadme), 0644)
    logInfoTemplates("Generated %s", readmePath)
    // create theme.json
    themeJsonPath := filepath.Join(themeDir, "theme.json")
    _ = os.WriteFile(themeJsonPath, []byte(themeJSONTemplate), 0644)
    // static files
    staticDir := filepath.Join(themeDir, "static")
    os.MkdirAll(staticDir, 0755)
    // create colorschemes
    colorsDir := filepath.Join(staticDir, "colorschemes")
    os.MkdirAll(colorsDir, 0755)
    for _, name := range []string{"catppuccin.css", "clean.css", "dracula.css", "github.css", "gruvbox.css", "iceberg.css", "minimal.css", "minimal_wb.css", "monokai.css", "nord.css", "one.css", "solarized.css", "typewriter.css"} {
        p := filepath.Join(colorsDir, name)
        _ = os.WriteFile(p, []byte("/* "+name+" */\n"), 0644)
        logInfoTemplates("Generated %s", p)
    }
    for _, name := range []string{"Atkinson-Hyperlegible-Regular-102.woff", "avatar-placeholder.png", "custom.css", "custom.js", "favicon.ico", "logo.png", "robots.txt", "search.js", "script.js", "style.css"} {
        p := filepath.Join(staticDir, name)
        content := ""
        if name == "custom.css" {
            content = "/* Custom CSS */\n"
        } else if name == "custom.js" {
            content = "// Custom JS\n"
        } else if name == "style.css" {
            content = getThemeStyleCSS()
        } else if name == "script.js" {
            content = getThemeScriptJS()
        }
        _ = os.WriteFile(p, []byte(content), 0644)
        logInfoTemplates("Generated %s", p)
    }
    templatesDir := filepath.Join(themeDir, "templates")
    os.MkdirAll(templatesDir, 0755)
    for name, content := range themeTemplates {
        p := filepath.Join(templatesDir, name)
        // For base.html we need full content from embedded? Use simplified
        if name == "base.html" {
            content = embeddedTemplates["base.html"]
        }
        _ = os.WriteFile(p, []byte(content), 0644)
        logInfoTemplates("Generated %s", p)
    }
    logInfoTemplates("Theme '%s' created successfully at %s", themeName, themeDir)
    logInfoTemplates("To use this theme, add 'theme: %s' to your marmite.yaml config file", themeName)
}

