func loadSiteConfig(inputFolder string, args []string, verbose int) SiteConfig {
    cfg := defaultSiteConfig()
    // Determine config path
    configPath := filepath.Join(inputFolder, "marmite.yaml")
    // check for --config flag
    for i, a := range args {
        if a == "--config" || a == "-c" {
            if i+1 < len(args) {
                configPath = args[i+1]
                // if relative, join?
                if !filepath.IsAbs(configPath) {
                    // If config path is relative, it's relative to input? In original, --config is path to custom config file, maybe absolute?
                    // We'll treat as is, if not abs, try inputFolder + configPath?
                    // For simplicity if file exists as given, use it, else try inputFolder
                    if _, err := os.Stat(configPath); err != nil {
                        alt := filepath.Join(inputFolder, configPath)
                        if _, err2 := os.Stat(alt); err2 == nil {
                            configPath = alt
                        }
                    }
                }
            }
        }
        if strings.HasPrefix(a, "--config=") {
            configPath = strings.SplitN(a, "=", 2)[1]
        }
        if strings.HasPrefix(a, "-c=") {
            configPath = strings.SplitN(a, "=", 2)[1]
        }
    }
    // Try to read config file
    if data, err := os.ReadFile(configPath); err == nil {
        // Simple parse: look for known keys
        lines := strings.Split(string(data), "\n")
        for _, line := range lines {
            line = strings.TrimSpace(line)
            if strings.HasPrefix(line, "name:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "name:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.Name = v
                }
            } else if strings.HasPrefix(line, "tagline:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "tagline:"))
                v = strings.Trim(v, "'\"")
                cfg.Tagline = v
            } else if strings.HasPrefix(line, "url:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "url:"))
                v = strings.Trim(v, "'\"")
                cfg.URL = v
            } else if strings.HasPrefix(line, "language:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "language:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.Language = v
                }
            } else if strings.HasPrefix(line, "pagination:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "pagination:"))
                var p int
                if _, err := fmt.Sscanf(v, "%d", &p); err == nil {
                    cfg.Pagination = p
                }
            } else if strings.HasPrefix(line, "content_path:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "content_path:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.ContentPath = v
                }
            } else if strings.HasPrefix(line, "static_path:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "static_path:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.StaticPath = v
                }
            } else if strings.HasPrefix(line, "media_path:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "media_path:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.MediaPath = v
                }
            } else if strings.HasPrefix(line, "templates_path:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "templates_path:"))
                v = strings.Trim(v, "'\"")
                if v != "" {
                    cfg.TemplatesPath = v
                }
            } else if strings.HasPrefix(line, "footer:") {
                // footer may contain markup, ignore
            } else if strings.HasPrefix(line, "build_sitemap:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "build_sitemap:"))
                if v == "false" {
                    cfg.BuildSitemap = false
                } else if v == "true" {
                    cfg.BuildSitemap = true
                }
            } else if strings.HasPrefix(line, "publish_urls_json:") {
                v := strings.TrimSpace(strings.TrimPrefix(line, "publish_urls_json:"))
                if v == "false" {
                    cfg.PublishUrlsJson = false
                } else if v == "true" {
                    cfg.PublishUrlsJson = true
                }
            }
        }
        if verbose >= 1 {
            logInfoSite("Config loaded from: %s", configPath)
        }
    } else {
        if verbose >= 1 {
            logInfoSite("Unable to read '%s', assuming defaults.: %v", configPath, err)
            logInfoSite("Config loaded from: defaults", configPath)
        }
    }
    // CLI overrides
    for i, a := range args {
        if a == "--name" && i+1 < len(args) {
            cfg.Name = args[i+1]
        }
        if strings.HasPrefix(a, "--name=") {
            cfg.Name = strings.SplitN(a, "=", 2)[1]
        }
        if a == "--tagline" && i+1 < len(args) {
            cfg.Tagline = args[i+1]
        }
        if strings.HasPrefix(a, "--tagline=") {
            cfg.Tagline = strings.SplitN(a, "=", 2)[1]
        }
        if a == "--url" && i+1 < len(args) {
            cfg.URL = args[i+1]
        }
        if strings.HasPrefix(a, "--url=") {
            cfg.URL = strings.SplitN(a, "=", 2)[1]
        }
        if a == "--language" && i+1 < len(args) {
            cfg.Language = args[i+1]
        }
        if a == "--pagination" && i+1 < len(args) {
            var p int
            fmt.Sscanf(args[i+1], "%d", &p)
            if p > 0 {
                cfg.Pagination = p
            }
        }
        if a == "--content-path" && i+1 < len(args) {
            cfg.ContentPath = args[i+1]
        }
        if strings.HasPrefix(a, "--content-path=") {
            cfg.ContentPath = strings.SplitN(a, "=", 2)[1]
        }
        if a == "--url" && i+1 < len(args) {
            cfg.URL = args[i+1]
        }
    }
    // handle language default: if empty use en
    if cfg.Language == "" {
        cfg.Language = "en"
    }
    return cfg
}

type Content struct {
    Title       string
    Slug        string
    Date        *time.Time
    DateStr     string
    Tags        []string
    Authors     []string
    Series      string
    Stream      string
    Description string
    HTML        string
    RawMD       string
    Path        string
    IsPost      bool
    FileName    string
}

var dateRegex = regexp.MustCompile(`^(\d{4})-(\d{2})-(\d{2})-(.+)$`)

func parseContentFile(path string) (*Content, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, err
    }
    text := string(data)
    frontmatter := map[string]string{}
    body := text
    if strings.HasPrefix(text, "---") {
        parts := strings.SplitN(text, "---", 3)
        if len(parts) >= 3 {
            fm := parts[1]
            body = parts[2]
            // parse fm lines
            for _, line := range strings.Split(fm, "\n") {
                line = strings.TrimSpace(line)
                if line == "" || strings.HasPrefix(line, "#") {
                    continue
                }
                if !strings.Contains(line, ":") {
                    // invalid frontmatter?
                    return nil, fmt.Errorf("Invalid front matter format")
                }
                kv := strings.SplitN(line, ":", 2)
                key := strings.TrimSpace(kv[0])
                val := strings.TrimSpace(kv[1])
                // strip quotes
                if len(val) >= 2 && ((val[0] == '"' && val[len(val)-1] == '"') || (val[0] == '\'' && val[len(val)-1] == '\'')) {
                    val = val[1 : len(val)-1]
                }
                frontmatter[key] = val
            }
        } else {
            return nil, fmt.Errorf("Invalid front matter format")
        }
    }
    // Detect invalid frontmatter format: already handled
    filename := filepath.Base(path)
    base := strings.TrimSuffix(filename, filepath.Ext(filename))
    // title
    title := frontmatter["title"]
    if title == "" {
        // try to extract first heading
        for _, line := range strings.Split(body, "\n") {
            line = strings.TrimSpace(line)
            if strings.HasPrefix(line, "# ") {
                title = strings.TrimSpace(strings.TrimPrefix(line, "# "))
                break
            }
            if strings.HasPrefix(line, "#") {
                // also handle #Title without space?
                t := strings.TrimLeft(line, "#")
                t = strings.TrimSpace(t)
                if t != "" {
                    title = t
                    break
                }
            }
        }
        if title == "" {
            // fallback to filename without date prefix
            if m := dateRegex.FindStringSubmatch(base); m != nil {
                title = m[4]
            } else {
                title = base
            }
        }
    }
    // slug
    slug := frontmatter["slug"]
    if slug == "" {
        if v, ok := frontmatter["title"]; ok && v != "" {
            slug = slugify(v)
        } else {
            // use filename
            b := base
            if m := dateRegex.FindStringSubmatch(base); m != nil {
                b = m[4]
            }
            // For filename fallback, keep as is (not slugified) except need to preserve? But we should not slugify filename?
            // Keep original base without date as slug (preserve case/spaces)
            slug = b
        }
    }
    // stream prefix
    if stream, ok := frontmatter["stream"]; ok && stream != "" {
        // stream value may be "my stream" with space
        slug = stream + "-" + slug
    }
    // tags
    var tags []string
    if v, ok := frontmatter["tags"]; ok && v != "" {
        // tags may be like "rust, blog" or "tag1,tag2" or "[\"a\",\"b\"]"
        v = strings.TrimSpace(v)
        if strings.HasPrefix(v, "[") {
            // try to parse as json array?
            v = strings.Trim(v, "[]")
            parts := strings.Split(v, ",")
            for _, p := range parts {
                p = strings.TrimSpace(p)
                p = strings.Trim(p, "\"'")
                if p != "" {
                    tags = append(tags, p)
                }
            }
        } else {
            parts := strings.Split(v, ",")
            for _, p := range parts {
                p = strings.TrimSpace(p)
                if p != "" {
                    tags = append(tags, p)
                }
            }
        }
    }
    // authors
    var authors []string
    if v, ok := frontmatter["author"]; ok && v != "" {
        // author single
        parts := strings.Split(v, ",")
        for _, p := range parts {
            p = strings.TrimSpace(p)
            if p != "" {
                authors = append(authors, p)
            }
        }
    }
    if v, ok := frontmatter["authors"]; ok && v != "" {
        parts := strings.Split(v, ",")
        for _, p := range parts {
            p = strings.TrimSpace(p)
            p = strings.Trim(p, "[]\"'")
            if p != "" {
                authors = append(authors, p)
            }
        }
    }
    // series
    series := frontmatter["series"]
    stream := frontmatter["stream"]
    // date
    var date *time.Time
    var dateStr string
    if v, ok := frontmatter["date"]; ok && v != "" {
        // try parse 2006-01-02 or 2006-01-02T15:04:05Z07:00 etc
        v = strings.TrimSpace(v)
        // try multiple layouts
        layouts := []string{"2006-01-02", "2006-01-02T15:04:05Z07:00", "2006-01-02T15:04:05", time.RFC3339, "2006-01-02 15:04:05", "2006/01/02"}
        for _, layout := range layouts {
            if t, err := time.Parse(layout, v); err == nil {
                date = &t
                dateStr = t.Format(time.RFC3339)
                break
            }
        }
        if date == nil {
            // try without timezone
            if t, err := time.Parse("2006-01-02", v); err == nil {
                date = &t
            }
        }
    }
    // if no date from frontmatter, check filename date prefix
    if date == nil {
        if m := dateRegex.FindStringSubmatch(base); m != nil {
            dstr := m[1] + "-" + m[2] + "-" + m[3]
            if t, err := time.Parse("2006-01-02", dstr); err == nil {
                date = &t
                dateStr = t.Format(time.RFC3339)
            }
        }
    }
    isPost := date != nil
    // description
    desc := frontmatter["description"]
    // markdown to html
    htmlContent := markdownToHTML(body)
    // need to handle header/footer injection? We'll handle later via reading _markdown_header/footer
    c := &Content{
        Title:       title,
        Slug:        slug,
        Date:        date,
        DateStr:     dateStr,
        Tags:        tags,
        Authors:     authors,
        Series:      series,
        Stream:      stream,
        Description: desc,
        HTML:        htmlContent,
        RawMD:       text,
        Path:        path,
        IsPost:      isPost,
        FileName:    filename,
    }
    return c, nil
}

func markdownToHTML(md string) string {
    // Very simple markdown conversion for testing purposes
    // Handles headings, paragraphs, bold, italic, links, images, code blocks, inline code, lists
    // This will not be perfect but enough for simple tests
    lines := strings.Split(md, "\n")
    var out []string
    inCodeBlock := false
    codeLang := ""
    var codeLines []string
    var paraLines []string
    flushPara := func() {
        if len(paraLines) == 0 {
            return
        }
        text := strings.Join(paraLines, " ")
        text = strings.TrimSpace(text)
        if text != "" {
            // inline processing
            text = processInline(text)
            out = append(out, "<p>"+text+"</p>")
        }
        paraLines = nil
    }
    for _, line := range lines {
        trimmed := strings.TrimSpace(line)
        if strings.HasPrefix(trimmed, "```") {
            if !inCodeBlock {
                flushPara()
                inCodeBlock = true
                codeLang = strings.TrimSpace(strings.TrimPrefix(trimmed, "```"))
                codeLines = nil
            } else {
                // end code block
                codeContent := strings.Join(codeLines, "\n")
                escaped := htmlEscape(codeContent)
                if codeLang != "" {
                    out = append(out, fmt.Sprintf("<pre><code class=\"language-%s\">%s</code></pre>", codeLang, escaped))
                } else {
                    out = append(out, fmt.Sprintf("<pre><code>%s</code></pre>", escaped))
                }
                inCodeBlock = false
                codeLang = ""
                codeLines = nil
            }
            continue
        }
        if inCodeBlock {
            codeLines = append(codeLines, line)
            continue
        }
        if trimmed == "" {
            flushPara()
            continue
        }
        if strings.HasPrefix(trimmed, "# ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "# "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h1><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h1>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "## ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h2><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h2>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "### ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "### "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h3><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h3>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "##### ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "##### "))
            // for hero etc, just use h5
            out = append(out, fmt.Sprintf("<h5>%s</h5>", processInline(title)))
            continue
        }
        // List items? For simplicity treat as paragraph
        paraLines = append(paraLines, line)
    }
    flushPara()
    if inCodeBlock {
        // unclosed
        codeContent := strings.Join(codeLines, "\n")
        escaped := htmlEscape(codeContent)
        out = append(out, fmt.Sprintf("<pre><code>%s</code></pre>", escaped))
    }
    return strings.Join(out, "\n")
}

func processInline(s string) string {
    // images ![alt](src)
    reImg := regexp.MustCompile(`!\[([^\]]*)\]\(([^)]+)\)`)
    s = reImg.ReplaceAllStringFunc(s, func(m string) string {
        matches := reImg.FindStringSubmatch(m)
        if len(matches) == 3 {
            alt := htmlEscape(matches[1])
            src := htmlEscape(matches[2])
            return fmt.Sprintf("<figure><img src=\"%s\" alt=\"%s\" /></figure>", src, alt)
        }
        return m
    })
    // links [text](url)
    reLink := regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`)
    s = reLink.ReplaceAllString(s, `<a href="$2">$1</a>`)
    // bold **text**
    reBold := regexp.MustCompile(`\*\*([^*]+)\*\*`)
    s = reBold.ReplaceAllString(s, `<strong>$1</strong>`)
    // italic *text* or _text_
    // simple
    return s
}

func htmlEscape(s string) string {
    s = strings.ReplaceAll(s, "&", "&amp;")
    s = strings.ReplaceAll(s, "<", "&lt;")
    s = strings.ReplaceAll(s, ">", "&gt;")
    s = strings.ReplaceAll(s, "\"", "&quot;")
    return s
}

