func slugify(s string) string {
    s = strings.ToLower(s)
    var b strings.Builder
    prevDash := false
    for _, r := range s {
        if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
            b.WriteRune(r)
            prevDash = false
        } else if r == ' ' || r == '-' || r == '_' {
            if !prevDash {
                b.WriteRune('-')
                prevDash = true
            }
        } else {
            if !prevDash {
                b.WriteRune('-')
                prevDash = true
            }
        }
    }
    res := strings.Trim(b.String(), "-")
    re := regexp.MustCompile(`-+`)
    res = re.ReplaceAllString(res, "-")
    if res == "" {
        res = "untitled"
    }
    return res
}

