func getPositionals(args []string, knownWithValue map[string]bool, boolFlags map[string]bool) []string {
    var pos []string
    i := 0
    for i < len(args) {
        a := args[i]
        if a == "--" {
            for _, rest := range args[i+1:] {
                pos = append(pos, rest)
            }
            break
        }
        if strings.HasPrefix(a, "--") {
            base := a
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
            } else {
                if _, ok := knownWithValue[base]; ok {
                    if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
                        i++
                    }
                }
            }
            i++
            continue
        } else if strings.HasPrefix(a, "-") && len(a) > 1 {
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                if a == "-c" || a == "-t" {
                    if i+1 < len(args) {
                        i += 2
                        continue
                    }
                }
                i++
                continue
            }
            if strings.HasPrefix(a, "-v") {
                allV := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        allV = false
                        break
                    }
                }
                if allV {
                    i++
                    continue
                }
            }
            i++
            continue
        } else {
            pos = append(pos, a)
            i++
        }
    }
    return pos
}

func hasFlag(args []string, flag string) bool {
    for _, a := range args {
        if a == flag {
            return true
        }
        if strings.HasPrefix(a, flag+"=") {
            return true
        }
    }
    return false
}

func getFlagValue(args []string, flag string) (string, bool) {
    for i, a := range args {
        if a == flag {
            if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
                return args[i+1], true
            } else if i+1 < len(args) && strings.HasPrefix(args[i+1], "-") {
                return "", false
            } else {
                return "", false
            }
        }
        if strings.HasPrefix(a, flag+"=") {
            return strings.SplitN(a, "=", 2)[1], true
        }
    }
    return "", false
}

