    _ = os.WriteFile(filepath.Join(inputFolder, "custom.css"), []byte(initSiteFiles["custom.css"]), 0644)
    _ = os.WriteFile(filepath.Join(inputFolder, "custom.js"), []byte(initSiteFiles["custom.js"]), 0644)
    ts := time.Now().UTC().Format("2006-01-02T15:04:05Z")
    fmt.Fprintf(os.Stderr, "[%s INFO  marmite::site] Site initialized in %s\n", ts, inputFolder)
