func markdownToHTML(md string) string {
    lines := strings.Split(md, "\n")
    var out []string
    inCodeBlock := false
    codeLang := ""
    var codeLines []string
    var paraLines []string
    flushPara := func() {
        if len(paraLines) == 0 {
            return
        }
        text := strings.Join(paraLines, " ")
        text = strings.TrimSpace(text)
        if text != "" {
            text = processInline(text)
            out = append(out, "<p>"+text+"</p>")
        }
        paraLines = nil
    }
    for _, line := range lines {
        trimmed := strings.TrimSpace(line)
        if strings.HasPrefix(trimmed, "```") {
            if !inCodeBlock {
                flushPara()
                inCodeBlock = true
                codeLang = strings.TrimSpace(strings.TrimPrefix(trimmed, "```"))
                codeLines = nil
            } else {
                codeContent := strings.Join(codeLines, "\n")
                escaped := htmlEscape(codeContent)
                if codeLang != "" {
                    out = append(out, fmt.Sprintf("<pre><code class=\"language-%s\">%s</code></pre>", codeLang, escaped))
                } else {
                    out = append(out, fmt.Sprintf("<pre><code>%s</code></pre>", escaped))
                }
                inCodeBlock = false
                codeLang = ""
                codeLines = nil
            }
            continue
        }
        if inCodeBlock {
            codeLines = append(codeLines, line)
            continue
        }
        if trimmed == "" {
            flushPara()
            continue
        }
        if strings.HasPrefix(trimmed, "# ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "# "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h1><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h1>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "## ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h2><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h2>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "### ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "### "))
            anchor := slugify(title)
            out = append(out, fmt.Sprintf("<h3><a href=\"#%s\" aria-hidden=\"true\" class=\"anchor\" id=\"%s\"></a>%s</h3>", anchor, anchor, htmlEscape(title)))
            continue
        }
        if strings.HasPrefix(trimmed, "##### ") {
            flushPara()
            title := strings.TrimSpace(strings.TrimPrefix(trimmed, "##### "))
            out = append(out, fmt.Sprintf("<h5>%s</h5>", processInline(title)))
            continue
        }
        paraLines = append(paraLines, line)
    }
    flushPara()
    if inCodeBlock {
        codeContent := strings.Join(codeLines, "\n")
        escaped := htmlEscape(codeContent)
        out = append(out, fmt.Sprintf("<pre><code>%s</code></pre>", escaped))
    }
    return strings.Join(out, "\n")
}

func processInline(s string) string {
    reImg := regexp.MustCompile(`!\[([^\]]*)\]\(([^)]+)\)`)
    s = reImg.ReplaceAllStringFunc(s, func(m string) string {
        matches := reImg.FindStringSubmatch(m)
        if len(matches) == 3 {
            alt := htmlEscape(matches[1])
            src := htmlEscape(matches[2])
            return fmt.Sprintf("<figure><img src=\"%s\" alt=\"%s\" /></figure>", src, alt)
        }
        return m
    })
    reLink := regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`)
    s = reLink.ReplaceAllString(s, `<a href="$2">$1</a>`)
    reBold := regexp.MustCompile(`\*\*([^*]+)\*\*`)
    s = reBold.ReplaceAllString(s, `<strong>$1</strong>`)
    return s
}

func htmlEscape(s string) string {
    s = strings.ReplaceAll(s, "&", "&amp;")
    s = strings.ReplaceAll(s, "<", "&lt;")
    s = strings.ReplaceAll(s, ">", "&gt;")
    s = strings.ReplaceAll(s, "\"", "&quot;")
    return s
}

func stripTags(html string) string {
    re := regexp.MustCompile(`<[^>]*>`)
    return re.ReplaceAllString(html, "")
}

