        if c.IsPost {
            posts = append(posts, c)
        } else {
            pages = append(pages, c)
        }
    }
    sort.Slice(posts, func(i, j int) bool {
        if posts[i].Date == nil || posts[j].Date == nil {
            return posts[i].Title < posts[j].Title
        }
        return posts[i].Date.After(*posts[j].Date)
    })
    sort.Slice(pages, func(i, j int) bool {
        return strings.ToLower(pages[i].Slug) < strings.ToLower(pages[j].Slug)
    })
    var mdHeader, mdFooter string
    contentDir := filepath.Join(inputFolder, cfg.ContentPath)
    if _, err := os.Stat(contentDir); err != nil {
        contentDir = inputFolder
    }
    if data, err := os.ReadFile(filepath.Join(contentDir, "_markdown_header.md")); err == nil {
        mdHeader = string(data)
    }
    if data, err := os.ReadFile(filepath.Join(contentDir, "_markdown_footer.md")); err == nil {
        mdFooter = string(data)
    }
    for _, c := range contents {
        html := c.HTML
        if mdHeader != "" {
            hdrHTML := markdownToHTML(mdHeader)
            html = hdrHTML + "\n" + html
        }
        if mdFooter != "" {
            ftrHTML := markdownToHTML(mdFooter)
            html = html + "\n" + ftrHTML
        }
        outPath := filepath.Join(outputFolder, c.Slug+".html")
        if strings.Contains(c.Slug, "/") {
            os.MkdirAll(filepath.Dir(outPath), 0755)
        }
        pageHTML := generateContentHTML(c, html, cfg)
        _ = os.WriteFile(outPath, []byte(pageHTML), 0644)
        if verbose >= 1 {
            logInfoSite("Generated %s", outPath)
        }
    }
    generate404(outputFolder, cfg, contentDir, verbose)
    generateListPage(filepath.Join(outputFolder, "index.html"), "Home", posts, cfg, 1, 1, verbose, "index.html")
    paginateList(posts, cfg.Pagination, outputFolder, "index", verbose, cfg)
    generateListPage(filepath.Join(outputFolder, "pages.html"), "Pages", pages, cfg, 1, 1, verbose, "pages.html")
    paginateList(pages, cfg.Pagination, outputFolder, "pages", verbose, cfg)
    tagsMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, t := range p.Tags {
            tagsMap[t] = append(tagsMap[t], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "tags.html"), "Tags", tagsMap, cfg, verbose, "tag")
    for tag, list := range tagsMap {
        slug := "tag-" + slugify(tag)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts tagged with '"+tag+"'", list, cfg, 1, 1, verbose, slug+".html")
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), tag, list, cfg)
    }
    authorsMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, a := range p.Authors {
            authorsMap[a] = append(authorsMap[a], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "authors.html"), "Authors", authorsMap, cfg, verbose, "author")
    for author, list := range authorsMap {
        slug := "author-" + slugify(author)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts by "+author, list, cfg, 1, 1, verbose, slug+".html")
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), author, list, cfg)
    }
    seriesMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Series != "" {
            seriesMap[p.Series] = append(seriesMap[p.Series], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "series.html"), "Series", seriesMap, cfg, verbose, "series")
    for s, list := range seriesMap {
        slug := "series-" + slugify(s)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+s+"' series", list, cfg, 1, 1, verbose, slug+".html")
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), s, list, cfg)
    }
    streamsMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Stream != "" {
            streamsMap[p.Stream] = append(streamsMap[p.Stream], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "streams.html"), "Streams", streamsMap, cfg, verbose, "stream")
    for s, list := range streamsMap {
        slug := slugify(s)
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+s+"'", list, cfg, 1, 1, verbose, slug+".html")
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), s, list, cfg)
    }
    archivesMap := make(map[string][]*Content)
    for _, p := range posts {
        if p.Date != nil {
            year := fmt.Sprintf("%d", p.Date.Year())
            archivesMap[year] = append(archivesMap[year], p)
        }
    }
    generateGroupPage(filepath.Join(outputFolder, "archive.html"), "Archive", archivesMap, cfg, verbose, "archive")
    for year, list := range archivesMap {
        slug := "archive-" + year
        generateListPage(filepath.Join(outputFolder, slug+".html"), "Posts from '"+year+"'", list, cfg, 1, 1, verbose, slug+".html")
        paginateList(list, cfg.Pagination, outputFolder, slug, verbose, cfg)
        generateRSS(filepath.Join(outputFolder, slug+".rss"), year, list, cfg)
    }
    if len(posts) > 0 {
        generateRSS(filepath.Join(outputFolder, "index.rss"), "index", posts, cfg)
    }
}

func paginateList(items []*Content, pagination int, outputFolder, base string, verbose int, cfg SiteConfig) {
    if pagination <= 0 {
        pagination = 10
    }
    total := len(items)
    if total == 0 {
        return
    }
    pages := (total + pagination - 1) / pagination
    for i := 1; i <= pages; i++ {
        start := (i - 1) * pagination
        end := start + pagination
        if end > total {
            end = total
        }
        slice := items[start:end]
        filename := fmt.Sprintf("%s-%d.html", base, i)
        outPath := filepath.Join(outputFolder, filename)
        title := ""
        if base == "index" {
            title = "Home"
        } else if base == "pages" {
            title = "Pages"
        } else {
            title = base
        }
        generateListPage(outPath, title, slice, cfg, i, pages, verbose, filename)
    }
}

func generateListPage(outPath, title string, items []*Content, cfg SiteConfig, current, total int, verbose int, currentPage string) {
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"color-scheme\" content=\"light dark\" />\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:title\" content=\"%s\">\n", htmlEscape(title)))
    sb.WriteString("    <meta property=\"og:description\" content=\"\">\n")
    sb.WriteString("    <meta property=\"og:type\" content=\"website\">\n")
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:site_name\" content=\"%s\">\n", htmlEscape(cfg.Name)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString("<header class=\"header-content\"><nav class=\"header-nav\"><ul class=\"header-name\"><li><hgroup class=\"h-card\"><h2><a href=\"/\" class=\"contrast p-name u-url\">" + htmlEscape(cfg.Name) + "</a></h2></hgroup></li></ul></nav></header>\n")
    sb.WriteString("<section class=\"main-content\">\n")
    if title != "" && currentPage != "index.html" {
        sb.WriteString(fmt.Sprintf("<div class=\"list-title\"><article><strong> %s </strong></article></div>\n", htmlEscape(title)))
    }
    sb.WriteString("<div class=\"content-list h-feed\">\n")
    if len(items) == 0 {
        sb.WriteString("<article class=\"content-list-item left\"><h2 class=\"content-title\">No content found</h2><p class=\"content-excerpt\">Add some markdown content and generate the site. &rarr; <a target=\"_blank\" href=\"https://marmite.blog/getting-started.html\">Getting Started</a></p></article>\n")
    } else {
        for _, c := range items {
            sb.WriteString("<article class=\"content-list-item h-entry\">\n")
            sb.WriteString(fmt.Sprintf("<h2 class=\"p-name\" style=\"display: none;\">%s</h2>\n", htmlEscape(c.Title)))
            sb.WriteString(fmt.Sprintf("<a class=\"u-url\" href=\"/%s.html\" style=\"display: none;\"></a>\n", c.Slug))
            if c.Date != nil {
                sb.WriteString(fmt.Sprintf("<time class=\"dt-published\" datetime=\"%s\" style=\"display: none;\">%s</time>\n", c.Date.Format(time.RFC3339), c.Date.Format("Jan 2, 2006")))
            }
            sb.WriteString(fmt.Sprintf("<div class=\"content-title-wrapper\"><h2 class=\"content-title\"><a href=\"/%s.html\">%s</a></h2></div>\n", c.Slug, htmlEscape(c.Title)))
            sb.WriteString("<p class=\"content-excerpt p-summary\">")
            if c.Description != "" {
                sb.WriteString(htmlEscape(c.Description))
            } else {
                txt := stripTags(c.HTML)
                if len(txt) > 250 {
                    txt = txt[:250] + " ..."
                }
                sb.WriteString(htmlEscape(txt))
            }
            sb.WriteString(fmt.Sprintf(" <a class=\"secondary\" href=\"/%s.html\">read more &rarr;</a></p>\n", c.Slug))
            if c.Date != nil {
                sb.WriteString("<footer class=\"data-tags-footer\">\n")
                sb.WriteString(fmt.Sprintf("<span class=\"content-date\"><a class=\"secondary\" href=\"/%s.html\">%s</a></span>\n", c.Slug, c.Date.Format("Jan 2, 2006")))
                if len(c.Tags) > 0 {
                    sb.WriteString("<ul class=\"content-tags overflow-auto\">\n")
                    for _, t := range c.Tags {
                        slug := "tag-" + slugify(t)
                        sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\" class=\"p-category\">%s</a></li>\n", slug, htmlEscape(t)))
                    }
                    sb.WriteString("</ul>\n")
                }
                sb.WriteString("</footer>\n")
            }
            sb.WriteString("</article>\n")
        }
    }
    if total > 1 {
        sb.WriteString("<div class=\"pagination\"><nav><ul>")
        if current > 1 {
            prev := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current-1)
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&larr;</strong></a></li>", prev))
        }
        sb.WriteString(fmt.Sprintf("<li><small>%d/%d</small></li>", current, total))
        if current < total {
            next := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current+1)
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&rarr;</strong></a></li>", next))
        }
        sb.WriteString("</ul></nav></div>")
    }
    sb.WriteString("</div>\n</section>\n")
    sb.WriteString(fmt.Sprintf("<footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generateGroupPage(outPath, title string, groupMap map[string][]*Content, cfg SiteConfig, verbose int, kind string) {
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"color-scheme\" content=\"light dark\" />\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(title), htmlEscape(cfg.Name)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString(fmt.Sprintf("<div class=\"list-title\"><article><strong> %s </strong></article></div>\n", htmlEscape(title)))
    sb.WriteString("<article class=\"group-details h-feed\">\n")
    sb.WriteString(fmt.Sprintf("<h1 class=\"p-name\" style=\"display: none;\">%s</h1>\n", htmlEscape(title)))
    if len(groupMap) > 0 {
        keys := make([]string, 0, len(groupMap))
        for k := range groupMap {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            var slug string
            if kind == "stream" {
                slug = slugify(k)
            } else {
                slug = kind + "-" + slugify(k)
            }
            sb.WriteString(fmt.Sprintf("<details><summary>%s (%d)</summary><ul>", htmlEscape(k), len(groupMap[k])))
            for _, c := range groupMap[k] {
                sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">%s</a></li>", c.Slug, htmlEscape(c.Title)))
            }
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">more &rarr;</a></li>", slug))
            sb.WriteString("</ul></details>")
        }
    }
    sb.WriteString("</article>\n</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generate404(outputFolder string, cfg SiteConfig, contentDir string, verbose int) {
    outPath := filepath.Join(outputFolder, "404.html")
    var title, html string
    if data, err := os.ReadFile(filepath.Join(contentDir, "_404.md")); err == nil {
        c, _ := parseContentFile(filepath.Join(contentDir, "_404.md"))
        if c != nil {
            title = c.Title
            html = c.HTML
        } else {
            title = "Not Found"
            html = markdownToHTML(string(data))
        }
    } else {
        title = "Not Found"
        html = "<p>Page not found</p>"
    }
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(title), htmlEscape(cfg.Name)))
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:title\" content=\"%s\">\n", htmlEscape(title)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString(fmt.Sprintf("<article class=\"h-entry\"><h1>%s</h1><div class=\"content-html e-content\">%s</div></article>\n", htmlEscape(title), html))
    sb.WriteString(fmt.Sprintf("<footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generateRSS(outPath, title string, items []*Content, cfg SiteConfig) {
    var sb strings.Builder
    sb.WriteString(`<?xml version="1.0" encoding="utf-8"?><rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/"><channel>`)
    sb.WriteString(fmt.Sprintf("<title>%s</title>", htmlEscape(cfg.Name)))
    sb.WriteString(fmt.Sprintf("<link>%s</link>", htmlEscape(cfg.URL)))
    sb.WriteString("<description></description>")
    if len(items) > 0 && items[0].Date != nil {
        sb.WriteString(fmt.Sprintf("<pubDate>%s</pubDate>", items[0].Date.Format(time.RFC1123Z)))
    }
    sb.WriteString(fmt.Sprintf("<lastBuildDate>%s</lastBuildDate>", time.Now().Format(time.RFC1123Z)))
    sb.WriteString("<generator>marmite</generator>")
    for _, c := range items {
        sb.WriteString("<item>")
        sb.WriteString(fmt.Sprintf("<title>%s</title>", htmlEscape(c.Title)))
        link := "/" + c.Slug + ".html"
        if cfg.URL != "" {
            link = strings.TrimSuffix(cfg.URL, "/") + link
        }
        sb.WriteString(fmt.Sprintf("<link>%s</link>", htmlEscape(link)))
        if c.Description != "" {
            sb.WriteString(fmt.Sprintf("<description><![CDATA[%s]]></description>", c.Description))
        } else {
            sb.WriteString(fmt.Sprintf("<description><![CDATA[%s]]></description>", c.HTML))
        }
        if len(c.Authors) > 0 {
            sb.WriteString(fmt.Sprintf("<author>%s</author>", htmlEscape(c.Authors[0])))
        }
        for _, t := range c.Tags {
            sb.WriteString(fmt.Sprintf("<category>%s</category>", htmlEscape(t)))
        }
        sb.WriteString(fmt.Sprintf("<guid>%s</guid>", htmlEscape(link)))
        if c.Date != nil {
            sb.WriteString(fmt.Sprintf("<pubDate>%s</pubDate>", c.Date.Format(time.RFC1123Z)))
        }
        sb.WriteString(fmt.Sprintf("<content:encoded><![CDATA[%s]]></content:encoded>", c.HTML))
        sb.WriteString("</item>")
    }
    sb.WriteString("</channel></rss>")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
}

