    sb.WriteString("    \"publisher\": {\"@type\": \"Organization\", \"name\": \"" + htmlEscape(cfg.Name) + "\", \"logo\": {\"@type\": \"ImageObject\", \"url\": \"/\"}},\n")
    if c.Date != nil {
        sb.WriteString(fmt.Sprintf("    \"datePublished\": \"%s\"\n", c.Date.Format(time.RFC3339)))
    } else {
        sb.WriteString("    \"datePublished\": \"\"\n")
