    sb.WriteString("}\n")
    sb.WriteString("</script>\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(c.Title), htmlEscape(cfg.Name)))
    sb.WriteString("    <link rel=\"stylesheet\" type=\"text/css\" href=\"/static/pico.min.css\">\n")
    sb.WriteString("    <link rel=\"stylesheet\" type=\"text/css\" href=\"/static/marmite.css\">\n")
