func loadContents(inputFolder string, cfg SiteConfig) []*Content {
    var contents []*Content
    var contentDir string
    cand := filepath.Join(inputFolder, cfg.ContentPath)
    if _, err := os.Stat(cand); err == nil {
        contentDir = cand
    } else {
        contentDir = inputFolder
    }
    filepath.Walk(contentDir, func(path string, info fs.FileInfo, err error) error {
        if err != nil {
            return nil
        }
        if info.IsDir() {
            return nil
        }
        if !strings.HasSuffix(strings.ToLower(info.Name()), ".md") {
            return nil
        }
        if strings.HasPrefix(info.Name(), ".") {
            return nil
        }
        if strings.HasPrefix(info.Name(), "_") && info.Name() != "_404.md" {
            return nil
        }
        c, err := parseContentFile(path)
        if err != nil {
            fmt.Fprintf(os.Stderr, "[%s ERROR marmite::site] Failed to process content: \"%s\"\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), err.Error())
            return nil
        }
        if strings.ToLower(info.Name()) == "index.md" {
            return nil
        }
        contents = append(contents, c)
        return nil
    })
    return contents
}

