                sb.WriteString("<footer class=\"data-tags-footer\">\n")
                sb.WriteString(fmt.Sprintf("<span class=\"content-date\"><a class=\"secondary\" href=\"/%s.html\">%s</a></span>\n", c.Slug, c.Date.Format("Jan 2, 2006")))
                if len(c.Tags) > 0 {
                    sb.WriteString("<ul class=\"content-tags overflow-auto\">\n")
                    for _, t := range c.Tags {
                        slug := "tag-" + slugify(t)
                        sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\" class=\"p-category\">%s</a></li>\n", slug, htmlEscape(t)))
                    }
                    sb.WriteString("</ul>\n")
                }
                sb.WriteString("</footer>\n")
            }
            sb.WriteString("</article>\n")
        }
    }
    if total > 1 {
        sb.WriteString("<div class=\"pagination\"><nav><ul>")
        if current > 1 {
            prev := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current-1)
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&larr;</strong></a></li>", prev))
        }
        sb.WriteString(fmt.Sprintf("<li><small>%d/%d</small></li>", current, total))
        if current < total {
            next := fmt.Sprintf("%s-%d.html", strings.TrimSuffix(currentPage, ".html"), current+1)
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s\"><strong>&rarr;</strong></a></li>", next))
        }
        sb.WriteString("</ul></nav></div>")
    }
    sb.WriteString("</div>\n</section>\n")
    sb.WriteString(fmt.Sprintf("<footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generateGroupPage(outPath, title string, groupMap map[string][]*Content, cfg SiteConfig, verbose int, kind string) {
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"color-scheme\" content=\"light dark\" />\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(title), htmlEscape(cfg.Name)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString(fmt.Sprintf("<div class=\"list-title\"><article><strong> %s </strong></article></div>\n", htmlEscape(title)))
    sb.WriteString("<article class=\"group-details h-feed\">\n")
    sb.WriteString(fmt.Sprintf("<h1 class=\"p-name\" style=\"display: none;\">%s</h1>\n", htmlEscape(title)))
    if len(groupMap) > 0 {
        keys := make([]string, 0, len(groupMap))
        for k := range groupMap {
            keys = append(keys, k)
        }
        sort.Strings(keys)
        for _, k := range keys {
            var slug string
            if kind == "stream" {
                slug = slugify(k)
            } else {
                slug = kind + "-" + slugify(k)
            }
            sb.WriteString(fmt.Sprintf("<details><summary>%s (%d)</summary><ul>", htmlEscape(k), len(groupMap[k])))
            for _, c := range groupMap[k] {
                sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">%s</a></li>", c.Slug, htmlEscape(c.Title)))
            }
            sb.WriteString(fmt.Sprintf("<li><a href=\"/%s.html\">more &rarr;</a></li>", slug))
            sb.WriteString("</ul></details>")
        }
    }
    sb.WriteString("</article>\n</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generate404(outputFolder string, cfg SiteConfig, contentDir string, verbose int) {
    outPath := filepath.Join(outputFolder, "404.html")
    var title, html string
    if data, err := os.ReadFile(filepath.Join(contentDir, "_404.md")); err == nil {
        c, _ := parseContentFile(filepath.Join(contentDir, "_404.md"))
        if c != nil {
            title = c.Title
            html = c.HTML
        } else {
            title = "Not Found"
            html = markdownToHTML(string(data))
        }
    } else {
        title = "Not Found"
        html = "<p>Page not found</p>"
    }
    var sb strings.Builder
    sb.WriteString("<!DOCTYPE html>\n<html lang=\"" + cfg.Language + "\">\n<head>\n")
    sb.WriteString("    <meta charset=\"UTF-8\">\n")
    sb.WriteString("    <link rel=\"icon\" type=\"image/x-icon\" href=\"/static/favicon.ico\">\n")
    sb.WriteString("    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
    sb.WriteString("    <meta name=\"generator\" content=\"Marmite\" />\n")
    sb.WriteString(fmt.Sprintf("    <title>%s | %s</title>\n", htmlEscape(title), htmlEscape(cfg.Name)))
    sb.WriteString(fmt.Sprintf("    <meta property=\"og:title\" content=\"%s\">\n", htmlEscape(title)))
    sb.WriteString("</head>\n<body>\n")
    sb.WriteString("<main class=\"container\">\n")
    sb.WriteString(fmt.Sprintf("<article class=\"h-entry\"><h1>%s</h1><div class=\"content-html e-content\">%s</div></article>\n", htmlEscape(title), html))
    sb.WriteString(fmt.Sprintf("<footer class=\"footer-content grid\"><div>%s</div></footer>\n", cfg.Footer))
    sb.WriteString("</main>\n</body>\n</html>\n")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
    if verbose >= 1 {
        logInfoSite("Generated %s", outPath)
    }
}

func generateRSS(outPath, title string, items []*Content, cfg SiteConfig) {
    var sb strings.Builder
    sb.WriteString(`<?xml version="1.0" encoding="utf-8"?><rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/"><channel>`)
    sb.WriteString(fmt.Sprintf("<title>%s</title>", htmlEscape(cfg.Name)))
    sb.WriteString(fmt.Sprintf("<link>%s</link>", htmlEscape(cfg.URL)))
    sb.WriteString("<description></description>")
    if len(items) > 0 && items[0].Date != nil {
        sb.WriteString(fmt.Sprintf("<pubDate>%s</pubDate>", items[0].Date.Format(time.RFC1123Z)))
    }
    sb.WriteString(fmt.Sprintf("<lastBuildDate>%s</lastBuildDate>", time.Now().Format(time.RFC1123Z)))
    sb.WriteString("<generator>marmite</generator>")
    for _, c := range items {
        sb.WriteString("<item>")
        sb.WriteString(fmt.Sprintf("<title>%s</title>", htmlEscape(c.Title)))
        link := "/" + c.Slug + ".html"
        if cfg.URL != "" {
            link = strings.TrimSuffix(cfg.URL, "/") + link
        }
        sb.WriteString(fmt.Sprintf("<link>%s</link>", htmlEscape(link)))
        if c.Description != "" {
            sb.WriteString(fmt.Sprintf("<description><![CDATA[%s]]></description>", c.Description))
        } else {
            sb.WriteString(fmt.Sprintf("<description><![CDATA[%s]]></description>", c.HTML))
        }
        if len(c.Authors) > 0 {
            sb.WriteString(fmt.Sprintf("<author>%s</author>", htmlEscape(c.Authors[0])))
        }
        for _, t := range c.Tags {
            sb.WriteString(fmt.Sprintf("<category>%s</category>", htmlEscape(t)))
        }
        sb.WriteString(fmt.Sprintf("<guid>%s</guid>", htmlEscape(link)))
        if c.Date != nil {
            sb.WriteString(fmt.Sprintf("<pubDate>%s</pubDate>", c.Date.Format(time.RFC1123Z)))
        }
        sb.WriteString(fmt.Sprintf("<content:encoded><![CDATA[%s]]></content:encoded>", c.HTML))
        sb.WriteString("</item>")
    }
    sb.WriteString("</channel></rss>")
    _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
}

