func generateUrlsAndSitemap(contents []*Content, cfg SiteConfig, outputFolder string, verbose int) {
    urls := generateUrls(contents, cfg)
    if cfg.PublishUrlsJson {
        data, _ := json.MarshalIndent(urls, "", "  ")
        outPath := filepath.Join(outputFolder, "urls.json")
        _ = os.WriteFile(outPath, data, 0644)
        if verbose >= 1 {
            logInfoSite("Generated urls.json")
        }
    }
    if cfg.BuildSitemap {
        var sitemapUrls []string
        prefix := ""
        if cfg.URL != "" {
            prefix = strings.TrimSuffix(cfg.URL, "/")
        }
        add := func(u string) {
            if prefix != "" {
                if strings.HasPrefix(u, "/") {
                    sitemapUrls = append(sitemapUrls, prefix+u)
                } else {
                    sitemapUrls = append(sitemapUrls, prefix+"/"+u)
                }
            } else {
                sitemapUrls = append(sitemapUrls, u)
            }
        }
        if arr, ok := urls["posts"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["pages"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["tags"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["authors"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["series"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["streams"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["archives"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["feeds"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["pagination"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        if arr, ok := urls["misc"].([]string); ok {
            for _, u := range arr { add(u) }
        }
        var sb strings.Builder
        sb.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
        sb.WriteString(`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">` + "\n")
        for _, u := range sitemapUrls {
            sb.WriteString("  <url>\n")
            sb.WriteString(fmt.Sprintf("    <loc>%s</loc>\n", htmlEscape(u)))
            sb.WriteString("  </url>\n")
        }
        sb.WriteString(`</urlset>`)
        outPath := filepath.Join(outputFolder, "sitemap.xml")
        _ = os.WriteFile(outPath, []byte(sb.String()), 0644)
        if verbose >= 1 {
            logInfoSite("Generated sitemap.xml with %d URLs", len(sitemapUrls))
        }
    }
}

func generateUrls(contents []*Content, cfg SiteConfig) map[string]interface{} {
    var posts []*Content
    var pages []*Content
    for _, c := range contents {
        if c.IsPost {
            posts = append(posts, c)
        } else {
            pages = append(pages, c)
        }
    }
    tagsMap := make(map[string][]*Content)
    authorsMap := make(map[string][]*Content)
    seriesMap := make(map[string][]*Content)
    streamsMap := make(map[string][]*Content)
    archivesMap := make(map[string][]*Content)
    for _, p := range posts {
        for _, t := range p.Tags {
            tagsMap[t] = append(tagsMap[t], p)
        }
        for _, a := range p.Authors {
            authorsMap[a] = append(authorsMap[a], p)
        }
        if p.Series != "" {
            seriesMap[p.Series] = append(seriesMap[p.Series], p)
        }
        if p.Stream != "" {
            streamsMap[p.Stream] = append(streamsMap[p.Stream], p)
        }
        if p.Date != nil {
            year := fmt.Sprintf("%d", p.Date.Year())
            archivesMap[year] = append(archivesMap[year], p)
        }
    }
    pagination := cfg.Pagination
    if pagination <= 0 {
        pagination = 10
    }
    var postsUrls []string
    for _, p := range posts {
        u := "/" + p.Slug + ".html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        postsUrls = append(postsUrls, u)
    }
    var pagesUrls []string
    for _, p := range pages {
        u := "/" + p.Slug + ".html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        pagesUrls = append(pagesUrls, u)
    }
    if len(pages) > 0 {
        u := "/pages.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        pagesUrls = append(pagesUrls, u)
    }
    var tagsUrls []string
    if len(tagsMap) > 0 {
        for tag := range tagsMap {
            slug := "tag-" + slugify(tag)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            tagsUrls = append(tagsUrls, u)
        }
        sort.Strings(tagsUrls)
        u := "/tags.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        tagsUrls = append(tagsUrls, u)
    }
    var authorsUrls []string
    if len(authorsMap) > 0 {
        for a := range authorsMap {
            slug := "author-" + slugify(a)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            authorsUrls = append(authorsUrls, u)
        }
        sort.Strings(authorsUrls)
        u := "/authors.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        authorsUrls = append(authorsUrls, u)
    }
    var seriesUrls []string
    if len(seriesMap) > 0 {
        for s := range seriesMap {
            slug := "series-" + slugify(s)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            seriesUrls = append(seriesUrls, u)
        }
        sort.Strings(seriesUrls)
        u := "/series.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        seriesUrls = append(seriesUrls, u)
    }
    var streamsUrls []string
    if len(streamsMap) > 0 {
        for s := range streamsMap {
            slug := slugify(s)
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            streamsUrls = append(streamsUrls, u)
        }
        sort.Strings(streamsUrls)
        u := "/streams.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        streamsUrls = append(streamsUrls, u)
    }
    var archivesUrls []string
    if len(archivesMap) > 0 {
        for year := range archivesMap {
            slug := "archive-" + year
            u := "/" + slug + ".html"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            archivesUrls = append(archivesUrls, u)
        }
        sort.Strings(archivesUrls)
        u := "/archive.html"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        archivesUrls = append(archivesUrls, u)
    }
    var feedsUrls []string
    if len(posts) > 0 {
        u := "/index.rss"
        if cfg.URL != "" {
            u = strings.TrimSuffix(cfg.URL, "/") + u
        }
        feedsUrls = append(feedsUrls, u)
        for tag := range tagsMap {
            slug := "tag-" + slugify(tag)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for a := range authorsMap {
            slug := "author-" + slugify(a)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for s := range seriesMap {
            slug := "series-" + slugify(s)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for s := range streamsMap {
            slug := slugify(s)
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        for year := range archivesMap {
            slug := "archive-" + year
            u := "/" + slug + ".rss"
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            feedsUrls = append(feedsUrls, u)
        }
        sort.Strings(feedsUrls)
    }
    var paginationUrls []string
    if len(pages) > 0 {
        cnt := (len(pages) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            u := fmt.Sprintf("/pages-%d.html", i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for tag, lst := range tagsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "tag-" + slugify(tag)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for a, lst := range authorsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "author-" + slugify(a)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for s, lst := range seriesMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "series-" + slugify(s)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for s, lst := range streamsMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := slugify(s)
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    for year, lst := range archivesMap {
        cnt := (len(lst) + pagination - 1) / pagination
        for i := 1; i <= cnt; i++ {
            slug := "archive-" + year
            u := fmt.Sprintf("/%s-%d.html", slug, i)
            if cfg.URL != "" {
                u = strings.TrimSuffix(cfg.URL, "/") + u
            }
            paginationUrls = append(paginationUrls, u)
        }
    }
    if len(posts) > 0 {
        cnt := (len(posts) + pagination - 1) / pagination
        if cnt > 1 {
            for i := 1; i <= cnt; i++ {
                u := fmt.Sprintf("/index-%d.html", i)
                if cfg.URL != "" {
                    u = strings.TrimSuffix(cfg.URL, "/") + u
                }
                paginationUrls = append(paginationUrls, u)
            }
        }
    }
    sort.Strings(paginationUrls)
    var miscUrls []string
    u := "/index.html"
    if cfg.URL != "" {
        u = strings.TrimSuffix(cfg.URL, "/") + u
    }
    miscUrls = []string{u}
    total := len(postsUrls) + len(pagesUrls) + len(tagsUrls) + len(authorsUrls) + len(seriesUrls) + len(streamsUrls) + len(archivesUrls) + len(feedsUrls) + len(paginationUrls) + len(miscUrls)
    summary := map[string]interface{}{
        "posts": len(posts),
        "pages": len(pagesUrls),
        "tags": len(tagsUrls),
        "authors": len(authorsUrls),
        "series": len(seriesUrls),
        "streams": len(streamsUrls),
        "archives": len(archivesUrls),
        "feeds": len(feedsUrls),
        "pagination": len(paginationUrls),
        "file_mappings": 0,
        "misc": len(miscUrls),
        "total": total,
        "meta": map[string]interface{}{
            "url": cfg.URL,
            "absolute_urls": cfg.URL != "",
        },
    }
    result := map[string]interface{}{
        "posts": postsUrls,
        "pages": pagesUrls,
        "tags": tagsUrls,
        "authors": authorsUrls,
        "series": seriesUrls,
        "streams": streamsUrls,
        "archives": archivesUrls,
        "feeds": feedsUrls,
        "pagination": paginationUrls,
        "file_mappings": []string{},
        "misc": miscUrls,
        "summary": summary,
    }
    // Ensure empty slices are not nil
    for k, v := range result {
        if arr, ok := v.([]string); ok && arr == nil {
            result[k] = []string{}
        }
    }
    return result
}

func generateMarmiteJson(contents []*Content, cfg SiteConfig, outputFolder string, start time.Time, verbose int) {
    var posts, pages int
    for _, c := range contents {
        if c.IsPost {
            posts++
        } else {
            pages++
        }
    }
    elapsed := time.Since(start).Seconds()
    now := time.Now()
    genAt := now.Format("2006-01-02 15:04:05.000000000 +00:00")
    ts := now.Unix()
    data := map[string]interface{}{
        "marmite_version": "0.2.7",
        "posts": posts,
        "pages": pages,
        "generated_at": genAt,
        "timestamp": ts,
        "elapsed_time": elapsed,
        "config": map[string]interface{}{
            "name": "Home",
            "tagline": "",
            "url": cfg.URL,
            "https": nil,
            "footer": cfg.Footer,
            "language": cfg.Language,
            "pagination": cfg.Pagination,
            "pages_title": "Pages",
            "tags_title": "Tags",
            "tags_content_title": "Posts tagged with '$tag'",
            "archives_title": "Archive",
            "archives_content_title": "Posts from '$year'",
            "streams_title": "Streams",
            "streams_content_title": "Posts from '$stream'",
            "series_title": "Series",
            "series_content_title": "Posts from '$series' series",
            "default_author": "",
            "authors_title": "Authors",
            "enable_search": false,
            "enable_related_content": true,
            "search_title": "Search",
            "content_path": cfg.ContentPath,
            "site_path": "",
            "templates_path": cfg.TemplatesPath,
            "static_path": cfg.StaticPath,
            "media_path": cfg.MediaPath,
            "card_image": "",
            "banner_image": "",
            "logo_image": "",
            "default_date_format": "%b %e, %Y",
            "menu": [][]string{{"Tags", "tags.html"}, {"Archive", "archive.html"}, {"Authors", "authors.html"}},
            "extra": nil,
            "authors": map[string]interface{}{},
            "streams": map[string]interface{}{},
            "series": map[string]interface{}{},
            "toc": false,
            "json_feed": false,
            "show_next_prev_links": true,
            "publish_md": false,
            "source_repository": nil,
            "image_provider": nil,
            "markdown_parser": nil,
            "theme": nil,
            "file_mapping": []string{},
            "enable_shortcodes": true,
            "shortcode_pattern": nil,
            "build_sitemap": cfg.BuildSitemap,
            "publish_urls_json": cfg.PublishUrlsJson,
            "gallery_path": "gallery",
            "gallery_create_thumbnails": true,
            "gallery_thumb_size": 50,
            "skip_image_resize": false,
        },
    }
    // Adjust name/language to cfg
    if cfg.Name != "Home" {
        data["config"].(map[string]interface{})["name"] = cfg.Name
    }
    if cfg.Tagline != "" {
        data["config"].(map[string]interface{})["tagline"] = cfg.Tagline
    }
    outPath := filepath.Join(outputFolder, "marmite.json")
    b, _ := json.MarshalIndent(data, "", "  ")
    _ = os.WriteFile(outPath, b, 0644)
    if verbose >= 1 {
        logInfoSite("Generated build info at marmite.json")
    }
}

func copyMedia(inputFolder string, cfg SiteConfig, outputFolder string, verbose int) {
    contentDir := filepath.Join(inputFolder, cfg.ContentPath)
    if _, err := os.Stat(contentDir); err != nil {
        contentDir = inputFolder
    }
    mediaSrc := filepath.Join(contentDir, cfg.MediaPath)
    if _, err := os.Stat(mediaSrc); err != nil {
        alt := filepath.Join(inputFolder, "media")
        if _, err2 := os.Stat(alt); err2 == nil {
            mediaSrc = alt
        } else {
            return
        }
    }
    if _, err := os.Stat(mediaSrc); err != nil {
        return
    }
    dstRoot := filepath.Join(outputFolder, cfg.MediaPath)
    filepath.Walk(mediaSrc, func(path string, info fs.FileInfo, err error) error {
        if err != nil {
            return nil
        }
        if info.IsDir() {
            return nil
        }
        rel, _ := filepath.Rel(mediaSrc, path)
        dst := filepath.Join(dstRoot, rel)
        os.MkdirAll(filepath.Dir(dst), 0755)
        data, _ := os.ReadFile(path)
        _ = os.WriteFile(dst, data, 0644)
        return nil
    })
    if verbose >= 1 {
        logInfoSite("Copied '%s' to '%s/'", mediaSrc, outputFolder)
    }
}

func generateStatic(outputFolder, inputFolder string, cfg SiteConfig, verbose int) {
    staticOut := filepath.Join(outputFolder, "static")
    os.MkdirAll(staticOut, 0755)
    colorsOut := filepath.Join(staticOut, "colorschemes")
    os.MkdirAll(colorsOut, 0755)
    staticFiles := map[string]string{
        "marmite.css": getMarmiteCSS(),
        "pico.min.css": getPicoCSS(),
        "marmite.js": getMarmiteJS(),
        "search.js": getSearchJS(),
        "custom.css": "",
        "custom.js": "",
        "favicon.ico": "",
        "logo.png": "",
        "robots.txt": "User-agent: Mediapartners-Google\nDisallow:\n\nUser-agent: *\nAllow: /\n",
    }
    colors := []string{"catppuccin.css", "clean.css", "dracula.css", "github.css", "gruvbox.css", "iceberg.css", "minimal.css", "minimal_wb.css", "monokai.css", "nord.css", "one.css", "solarized.css", "typewriter.css"}
    for name, content := range staticFiles {
        p := filepath.Join(staticOut, name)
        if name == "Atkinson-Hyperlegible-Regular-102.woff" || name == "avatar-placeholder.png" {
            continue
        }
        _ = os.WriteFile(p, []byte(content), 0644)
        if verbose >= 1 {
            logInfoEmbedded("Generated %s", p)
        }
    }
    // handle binary via base64 map
    for name, b64 := range staticFilesBase64 {
        p := filepath.Join(staticOut, name)
        data, _ := base64.StdEncoding.DecodeString(b64)
        _ = os.WriteFile(p, data, 0644)
        if verbose >= 1 {
            logInfoEmbedded("Generated %s", p)
        }
    }
    for _, name := range colors {
        p := filepath.Join(colorsOut, name)
        _ = os.WriteFile(p, []byte("/* "+name+" */\n"), 0644)
        if verbose >= 1 {
            logInfoEmbedded("Generated %s", p)
        }
    }
    staticSrc := filepath.Join(inputFolder, cfg.StaticPath)
    if _, err := os.Stat(staticSrc); err == nil {
        filepath.Walk(staticSrc, func(path string, info fs.FileInfo, err error) error {
            if err != nil {
                return nil
            }
            if info.IsDir() {
                return nil
            }
            rel, _ := filepath.Rel(staticSrc, path)
            dst := filepath.Join(staticOut, rel)
            os.MkdirAll(filepath.Dir(dst), 0755)
            data, _ := os.ReadFile(path)
            _ = os.WriteFile(dst, data, 0644)
            return nil
        })
    }
    for _, name := range []string{"custom.css", "custom.js"} {
        src := filepath.Join(inputFolder, name)
        if _, err := os.Stat(src); err == nil {
            dst := filepath.Join(staticOut, name)
            data, _ := os.ReadFile(src)
            _ = os.WriteFile(dst, data, 0644)
        }
    }
    if verbose >= 1 {
        for _, name := range []string{"custom.css", "custom.js", "favicon.ico", "robots.txt"} {
            src := filepath.Join(staticOut, name)
            fmt.Fprintf(os.Stderr, "[%s INFO  marmite::site] Copied %s to %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), src, src)
        }
        robotsSrc := filepath.Join(staticOut, "robots.txt")
        robotsDst := filepath.Join(outputFolder, "robots.txt")
        _ = os.WriteFile(robotsDst, []byte("User-agent: Mediapartners-Google\nDisallow:\n\nUser-agent: *\nAllow: /\n"), 0644)
        fmt.Fprintf(os.Stderr, "[%s INFO  marmite::site] Copied %s to %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), robotsSrc, robotsDst)
    } else {
        _ = os.WriteFile(filepath.Join(outputFolder, "robots.txt"), []byte("User-agent: Mediapartners-Google\nDisallow:\n\nUser-agent: *\nAllow: /\n"), 0644)
    }
}

