    for _, a := range args {
        if strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
            if a == "-v" || a == "-w" || a == "-c" || a == "-e" || a == "-p" || a == "-t" || a == "-h" || a == "-V" {
                continue
            }
            if strings.HasPrefix(a, "-v") {
                ok := true
                for _, ch := range a[1:] {
                    if ch != 'v' {
                        ok = false
                        break
                    }
                }
                if ok {
                    continue
                }
            }
            if _, ok := boolFlags[a]; ok {
                continue
            }
            if _, ok := knownWithValue[a]; ok {
                continue
            }
            fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n", a, a, a)
            os.Exit(2)
        } else if strings.HasPrefix(a, "--") {
            base := a
            if strings.Contains(a, "=") {
                parts := strings.SplitN(a, "=", 2)
                base = parts[0]
            }
            if _, ok := boolFlags[base]; ok {
                continue
